async () => {
  const pj = await fetch('/collections/all/products.json?limit=250').then(r => r.json());
  const handles = pj.products.map(p => p.handle);
  window.__handles = handles;
  const pages = [];
  const t0 = performance.now();
  for (let p = 0; p < 5; p++) {
    const batch = handles.slice(p * 36, p * 36 + 36);
    const start = performance.now();
    const res = await Promise.all(batch.map(async h => {
      const s = performance.now();
      try {
        const r = await fetch(`/products/${h}?section_id=api-product-grid-item`);
        const txt = await r.text();
        return { status: r.status, ms: Math.round(performance.now() - s), cf: r.headers.get('cf-mitigated'), cache: r.headers.get('cf-cache-status'), bytes: txt.length };
      } catch (e) { return { status: 'ERR', ms: Math.round(performance.now() - s) }; }
    }));
    const ms = res.map(r => r.ms).sort((a, b) => a - b);
    const statuses = {}; res.forEach(r => statuses[r.status] = (statuses[r.status] || 0) + 1);
    const caches = {}; res.forEach(r => caches[r.cache] = (caches[r.cache] || 0) + 1);
    const first8 = res.slice(0, 8).map(r => r.ms).sort((a, b) => a - b);
    pages.push({ page: p + 1, statuses, challenged: res.filter(r => r.cf).length, caches, wallMs: Math.round(performance.now() - start), p50: ms[18], p75: ms[27], max: ms[35], first8Max: first8[7], avgKB: Math.round(res.reduce((a, r) => a + (r.bytes || 0), 0) / res.length / 1024) });
    await new Promise(r => setTimeout(r, 1500));
  }
  return { totalHandles: handles.length, totalMs: Math.round(performance.now() - t0), pages };
}

