input.function:
async () => {
  if (window.Shopify?.theme?.id !== 157709861001) return { wrongTheme: window.Shopify?.theme };
  const pjRes = await fetch('/collections/all/products.json?limit=250', { cache: 'no-store' });
  if (!pjRes.ok) return { productsJson: pjRes.status, cf: pjRes.headers.get('cf-mitigated') };
  const handles = (await pjRes.json()).products.map(p => p.handle);
  window.__handles = handles;
  const pages = [];
  for (let p = 0; p < 5; p++) {
    const start = performance.now();
    const res = await Promise.all(handles.slice(p * 36, p * 36 + 36).map(async h => {
      const s = performance.now();
      try {
        const r = await fetch(`/products/${h}?section_id=api-product-grid-item`, { cache: 'no-store' });
        await r.text();
        return { s: r.status, cf: r.headers.get('cf-mitigated'), ms: Math.round(performance.now() - s) };
      } catch (e) { return { s: 'ERR', ms: Math.round(performance.now() - s) }; }
    }));
    const ms = res.map(r => r.ms).sort((a, b) => a - b);
    const by = {}; res.forEach(r => by[r.s] = (by[r.s] || 0) + 1);
    pages.push({ page: p + 1, statuses: by, challenged: res.filter(r => r.cf).length, wallMs: Math.round(performance.now() - start), p75: ms[27], first8Max: res.slice(0, 8).map(r => r.ms).sort((a, b) => a - b)[7] });
    await new Promise(r => setTimeout(r, 1500));
  }
  return { themeId: Shopify.theme.id, pages };
}

