content.content:
     1	{%- liquid
     2	  assign enable_sort = section.settings.enable_sort
     3	  assign enable_filters = section.settings.enable_filters
     4	  assign filter_layout = section.settings.filter_layout
     5	  assign hidden_products_count = 0
     6	  assign show_recently_viewed_indicator = settings.show_recently_viewed_indicator
     7	  assign color_scheme = 'color-' | append: section.settings.color_scheme
     8	
     9	  assign columns_desktop = 4
    10	  assign columns_medium = 3
    11	  assign columns_small = 2
    12	  assign columns_mobile = section.settings.grid_mobile | plus: 0
    13	
    14	  if filter_layout == 'inline-open'
    15	    assign show_group_filters = true
    16	  endif
    17	-%}
    18	
    19	{%- capture collection_sidebar_class -%}
    20	  {%- if filter_layout == 'slide-out' -%}
    21	    collection__sidebar__slide-out
