    23	    collection__sidebar__slider{% if show_group_filters %} expanded drawer--animated no-mobile-animation{% endif %}
    24	  {%- endif -%}
    25	{%- endcapture -%}
    26	
    27	{%- render 'stylesheet', name: 'collections.css' -%}
    28	
    29	{%- if enable_sort or enable_filters -%}
    30	  {%- render 'stylesheet', name: 'collection-bar.css' -%}
    31	{%- endif -%}
