{%- liquid
  assign default_mode = section.settings.card_image_mode | default: 'model'
-%}
<collection-model-switcher class="collection__model" data-default-mode="{{ default_mode }}">
  <button type="button" class="collection__model--button{% if default_mode != 'product' %} is-active{% endif %}" data-toggle-button="model">Model</button>
  <span class="collection__model--separator">|</span>
  <button type="button" class="collection__model--button{% if default_mode == 'product' %} is-active{% endif %}" data-toggle-button="ghost">Product</button>
</collection-model-switcher>
#### js
(() => {
  'use strict';

  if (customElements.get('collection-model-switcher')) return;

  const SWAP_ATTRS = ['src', 'srcset', 'sizes', 'width', 'height', 'alt'];

  function swapImgAttrs(imgA, imgB) {
    if (!imgA || !imgB) return;
    SWAP_ATTRS.forEach(attr => {
      const temp = imgA.getAttribute(attr);
      imgA.setAttribute(attr, imgB.getAttribute(attr) || '');
      imgB.setAttribute(attr, temp || '');
    });
  }

  function copyAttrsToImg(sourceAttrs, targetImg) {
    if (!targetImg || !sourceAttrs) return;
    SWAP_ATTRS.forEach(attr => {
      targetImg.setAttribute(attr, sourceAttrs[attr] || '');
    });
  }

  function readAttrs(img) {
    if (!img) return null;
    const attrs = {};
    SWAP_ATTRS.forEach(attr => { attrs[attr] = img.getAttribute(attr) || ''; });
    return attrs;
  }

  customElements.define('collection-model-switcher', class extends HTMLElement {
    connectedCallback() {
      this.collection = this.closest('collection-component');
      // Cards may be server-rendered ghost-first, so trust the section setting, not a constant.
      this.isGhostMode = this.dataset.defaultMode === 'product';
