content.content:
{%- comment -%}
  Everything a product grid needs to stay within a mobile browser's memory budget.
  Render immediately BEFORE the grid markup, in every section that renders one.

  The inline part must stay inline and un-deferred: WebKit restores scroll before
  DOMContentLoaded on a back/forward, so a deferred script is already too late.

  Why any of this exists: ../vault/04-engineering/patterns/plp-infinite-scroll-and-swatch-fetch.md
{%- endcomment -%}

<script>
  (function () {
    if (window.__rsGridGuardInit) return; // two grids on one page
    window.__rsGridGuardInit = true;

    // Infinite scroll leaves the URL alone, so a reload or a back/forward rebuilds the
    // first page only — and the browser reapplies an offset it saved against a much
    // longer document, landing the shopper past the end of it. WebKit reapplies late and
    // more than once, so hold the top until the shopper touches the page. A bfcache
    // restore never runs this and keeps its own position.
    var nav = (performance.getEntriesByType('navigation') || [])[0];
    var type = (nav && nav.type) || '';
    window.__rsScrollGuard = 'armed:' + type;
    if (type !== 'reload' && type !== 'back_forward') return;
    window.__rsScrollGuard = 'active';

    if ('scrollRestoration' in history) history.scrollRestoration = 'manual';

    var release = false;
    var stop = function () {
      if (release) return;
      release = true;
      if ('scrollRestoration' in history) history.scrollRestoration = 'auto';
    };
    ['touchstart', 'wheel', 'keydown', 'pointerdown'].forEach(function (e) {
      addEventListener(e, stop, { once: true, passive: true });
    });

    // Event-driven rather than polling: reading scrollY every frame during load forces
    // layout, and this runs in the critical rendering window.
    addEventListener('scroll', function () {
      if (!release && window.scrollY !== 0) window.scrollTo(0, 0);
    }, { passive: true });
    window.scrollTo(0, 0);
    addEventListener('load', function () {
      if (!release && window.scrollY !== 0) window.scrollTo(0, 0);
    });

    setTimeout(stop, 2000); // never pinned indefinitely
  })();
</script>

