    const distant = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const card = entry.target;
          if (entry.isIntersecting) {
            card.querySelectorAll('img').forEach((img) => {
              restore(img);
              markLoaded(img);
            });
          } else {
            const keep = visibleImage(card);
            card.querySelectorAll('img').forEach((img) => {
              if (img !== keep) release(img);
            });
          }
        });
