    // never be in play when it runs. Only the released ones need touching — walking every
    // image on the page meant ~1,500 attribute writes and a burst of requests.
    document.addEventListener('click', (event) => {
      if (!event.target.closest || !event.target.closest('.collection__model--button')) return;
      grids.forEach((grid) => grid.querySelectorAll('img[data-rs-src]').forEach(restore));
    }, true);

    // First contact with a card: give it the rest of its slides.
    document.addEventListener('touchstart', (event) => {
      const card = event.target.closest && event.target.closest(CARD);
      if (card) attach(card);
    }, { capture: true, passive: true });

