import Products from "@/components/Products/Products"
import Toolbar from "@/components/Toolbar/Toolbar"
import Pagination from "@/components/Pagination/Pagination"
import { ContentChildrenProps, wrapContent } from "@/components/ContentWrapper/ContentWrapper"
import { InfiniteScroll } from "@nosto/search-js/preact/common"
import { useNostoAppState } from "@nosto/search-js/preact/hooks"
import NoResults from "@/components/NoResults/NoResults"
import { infiniteScroll } from "@/config"
import { ComponentChildren } from "preact"
import { cl } from "@nosto/search-js/utils"

/**
 * Search page layout mirrors sections/search.liquid: caption, collection nav, then the products grid.
 */
export function SerpBody({ foundProducts, loading }: ContentChildrenProps) {
  if (!foundProducts && !loading) return <NoResults />
  return (
    <>
      <ResultsCount loading={loading} />
      <Toolbar />
      <ProductsGrid loading={loading}>
        <Products />
        <Pagination />
      </ProductsGrid>
    </>
  )
}

export function SerpBodyInfiniteScroll({ foundProducts, loading }: ContentChildrenProps) {
  if (!foundProducts && !loading) return <NoResults />
  return (
    <>
      <ResultsCount loading={loading} />
      <Toolbar />
      <ProductsGrid loading={loading}>
        <InfiniteScroll
          observerOptions={{
            rootMargin: "50% 0px"
          }}
        >
          <Products />
        </InfiniteScroll>
      </ProductsGrid>
    </>
  )
}

/**
 * `.collection__products > .grid-outer` gives the grid its theme padding; `is-loading` shows the theme's
 * loader line (.grid__loader) while the next page or sort is fetched.
 */
function ProductsGrid({ loading, children }: { loading: boolean; children: ComponentChildren }) {
  return (
    <div className="collection__products">
      <div className={cl("grid-outer", loading && "is-loading")}>
        {children}
        <div className="grid__loader">
          <div className="loader grid__loader-line">
            <div className="loader-indeterminate" />
          </div>
        </div>
      </div>
    </div>
  )
}

function ResultsCount({ loading }: { loading: boolean }) {
  const { total, query } = useNostoAppState(state => ({
    total: state.response.products?.total ?? 0,
    query: state.response.query
  }))

  return (
    <p className="search__caption caps" data-results-count data-nosto-element="totalResults">
      {loading ? "\u00a0" : `${total} ${total === 1 ? "result" : "results"} found for "${query}"`}
    </p>
  )
}

const Component = infiniteScroll ? SerpBodyInfiniteScroll : SerpBody
export default wrapContent("search", Component)
import { pick } from "@nosto/search-js/utils"
import ThemeProductCard from "@/components/Product/ThemeProductCard"
import { useDecoratedSearchResults, useNostoAppState } from "@nosto/search-js/preact/hooks"
import { hitDecorators } from "@/config"

/**
 * Theme grid markup from sections/search.liquid, so theme.css lays out the cards.
 */
export default function Products() {
  const { loading } = useNostoAppState(state => pick(state, "loading"))
  const { products } = useDecoratedSearchResults<typeof hitDecorators>()

  return (
    <div className="grid" id="SearchLoop" aria-busy={loading}>
      {products?.hits.map((hit, index) => (
        <ThemeProductCard product={hit} key={hit.productId || index} />
      ))}
    </div>
  )
}
import { useFacets, useSelectedFiltersCount, useSort } from "@nosto/search-js/preact/hooks"
import { cl } from "@nosto/search-js/utils"
import { useState, useRef, useCallback } from "preact/hooks"
import { sortOptions } from "@/config"
import { useFilterSidebar } from "@/contexts/SidebarContext"
import { useDomEvents } from "@/hooks/useDomEvents"
import ThemeIcon from "@/elements/ThemeIcon/ThemeIcon"
import { getCurrentUrlState } from "@/mapping/url/getCurrentUrlState"
import { getUrlFromState } from "@/mapping/url/getUrlFromState"

/**
 * Filter button and sort dropdown using the theme's collection nav markup (sections/search.liquid,
 * snippets/collection-sorting.liquid), so collection-bar.css styles them.
 */
export default function Toolbar() {
  // Facets are set up in Nosto Admin (Search → Facets); without them there is nothing to filter
  const { facets } = useFacets()
  const hasFacets = !!facets?.length

  return (
    <nav
      aria-label="Sort and filters"
      className={cl("collection__nav collection__nav--sort", hasFacets && "collection__nav--filter")}
    >
      {hasFacets && <FilterButton />}
      <SortPopout />
    </nav>
  )
}

function FilterButton() {
  const { isOpen, toggle } = useFilterSidebar()
  const selectedFiltersCount = useSelectedFiltersCount()

  return (
    <div className="popout--group">
      <button type="button" className="popout__toggle" aria-expanded={isOpen} onClick={toggle}>
        <ThemeIcon name="filter" />
        Filters
        {selectedFiltersCount > 0 && <span className="filter-count">{selectedFiltersCount}</span>}
      </button>
    </div>
  )
}

function SortPopout() {
  const { activeSort, setSort } = useSort(sortOptions)
  const [open, setOpen] = useState(false)
  const popoutRef = useRef<HTMLDivElement>(null)
  const active = sortOptions.find(option => option.id === activeSort)

  const onClickOutside = useCallback((e: MouseEvent) => {
    if (!popoutRef.current?.contains(e.target as Node)) {
      setOpen(false)
    }
  }, [])

  useDomEvents(open ? document.body : null, { onClick: onClickOutside })

  function onSelect(e: Event, id: string) {
    e.preventDefault()
    setSort(id)
    setOpen(false)
  }

  return (
    <div className="popout--sort">
      <div className={cl("popout", active && "is-active")} ref={popoutRef}>
        <button
          type="button"
          className="popout__toggle"
          aria-expanded={open}
          aria-controls="NostoSortList"
          onClick={() => setOpen(!open)}
        >
          <span className="popout__toggle__text">Sort by</span>
          <span className="popout__toggle__text">{active?.value.name}</span>
          <ThemeIcon name="nav-arrow-down" />
        </button>
        <ul id="NostoSortList" className={cl("popout-list", open && "popout-list--visible")}>
          {sortOptions.map(option => (
            <li key={option.id} className={cl("popout-list__item", option.id === activeSort && "is-active")}>
              <a
                className="popout-list__option"
                href={getUrlFromState({ ...getCurrentUrlState(), sort: option.value.sort, page: undefined })}
                aria-current={option.id === activeSort}
                onClick={e => onSelect(e, option.id)}
              >
                <span>{option.value.name}</span>
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  )
}
