input.content:
{% comment %}
  Nosto dynamic card: search results grid.
  Section Rendering only: <nosto-dynamic-card> fetches /products/{handle}?section_id=api-nosto-product-card.
  Template code: roswell-studios/Elie_Tahari_TAHARI_Nosto.

  Don't reuse api-product-grid-item: its '||itemAnimationAnchor||' placeholder makes the AOS observer
  throw when the card is injected. aos_anchor is left out so the card anchors to its own id.

  Section Rendering has no section.settings, so everything search.liquid reads from them is passed
  explicitly: sizes (search.liquid's non-inline-filter branch), columns_mobile (templates/search.json
  grid_mobile) and index 99, which keeps the card off the eager/fetchpriority path. Card image mode
  is always 'model' here; collection-model-switcher.js applies Product mode client-side.
{% endcomment %}

{%- liquid
  assign columns_mobile = 2
-%}

{%- capture rs_nosto_sizes -%}
  {%- if settings.grid_style == 'compact' -%}
    (min-width: 990px) calc((100vw) / 4), (min-width: 750px) calc((100vw) / 3), (min-width: 480px) calc(100vw / 2), calc(100vw / {{ columns_mobile }})
  {%- else -%}
    (min-width: 990px) calc((100vw - 100px) / 4 - 32px), (min-width: 750px) calc((100vw - 64px) / 3 - 32px), (min-width: 480px) calc((100vw - 32px) / 2), calc((100vw - 32px) / {{ columns_mobile }})
  {%- endif -%}
{%- endcapture -%}

<div data-api-content>
  {%- render 'product-grid-item',
    product: product,
    index: 99,
    sizes: rs_nosto_sizes,
    columns_mobile: columns_mobile,
    card_image_mode: 'model',
    aos_delay: 0
  -%}
</div>

{% schema %}
{
  "name": "Nosto product card",
  "settings": []
}
{% endschema %}

