import { createSortOption } from "./utils/sorting"
import { thumbnailDecorator } from "@nosto/search-js/thumbnails"
import { priceDecorator } from "@nosto/search-js/currencies"
import { AutocompleteConfig } from "@nosto/search-js/preact/autocomplete"
import { SerpConfig } from "@nosto/search-js/preact/serp"
import { handleDecorator } from "./decorators"
import { CategoryConfig } from "@nosto/search-js/preact/category"
import { InputSearchFilter, SearchQuery } from "@nosto/nosto-js/client"
import { tagging } from "./mapping/tagging"
import { pipe } from "./utils/pipe"

export const sizes = [36, 72, 108]

export const sortOptions = [
  createSortOption("score", "Relevance", { field: "_score", order: "desc" }),
  createSortOption("price", "Price, low to high", { field: "price", order: "asc" }),
  createSortOption("-price", "Price, high to low", { field: "price", order: "desc" })
]

/**
 * Enable or disable infinite scroll for search results
 */
export const infiniteScroll = false

/**
 * Enable or disable skeleton loading state for search results
 */
export const skeletonLoading = true

/**
 * Enable or disable search redirect on search form submit
 */
export const redirectOnSearch = true

export const shopifyMode = !!window.Shopify

/**
 * Theme product cards come from the Shopify theme
 * So outside a production build they render the web component's mock card instead of fetching the dev page.
 */
export const mockThemeCards = !import.meta.env.PROD

/**
 * Default sort option for search results and categories
 */
export const defaultSort = sortOptions[0]

/**
 * Default page size for search results and categories
 */
export const defaultSize = sizes[0]

/**
 * Path to the search page
 */
export const searchPath = "/search"

/**
 * CSS selectors for the Injected mode. The mount points come from the theme when the
 * "Use Nosto search" theme setting (rs_nosto_search_enabled) is on.
 */
export const selectors = {
  // autocomplete dropdown, one per header search popdown (desktop, mobile, mobile menu)
  dropdown: "[data-nosto-autocomplete]",
  // search input and form, looked up inside the dropdown's own form
  searchInput: 'input[name="q"]',
  searchForm: "form",
  // search page results (sections/search.liquid)
  results: "[data-nosto-search]"
}

/**
 * Base hit decorator definitions for the search results.
 *
 * Decorators are transformer functions applied in order to all results returned
 * from the search backend. You may define your own decorators using `handleDecorator`
 * as an example.
 * The type for decorated products is defined in `src/types.ts`.
 */
export const hitDecorators = [handleDecorator, priceDecorator()] as const

/**
 * Shared configuration for all page types (Autocomplete, Category, Search)
 */
export const baseConfig = {
  search: {
    hitDecorators
  },
  queryModifications: withBaseConfig
}

/**
 * Products tagged `hide` render nothing in the theme card (product-grid-item.liquid), so exclude them
 * before facet counting to keep grid slots and result counts right.
 */
const hiddenProductsFilter: InputSearchFilter = { not: [{ field: "tags1", value: ["hide"] }] }

function withHiddenProductsFilter(preFilter: InputSearchFilter[] = []) {
  return preFilter.includes(hiddenProductsFilter) ? preFilter : [...preFilter, hiddenProductsFilter]
}

export function withBaseConfig(query: SearchQuery) {
  return {
    ...query,
    products: {
      size: defaultSize,
      ...query.products,
      preFilter: withHiddenProductsFilter(query.products?.preFilter)
      // uncomment for exchange rates based multi-currency support
      //currency: tagging.variation() ?? defaultCurrency

      // uncomment for price variation based multi-currency support
      //variationId: tagging.variation() ?? defaultCurrency
    }
  } satisfies SearchQuery
}

/**
 * Autocomplete configuration
 */

export const autocompleteConfig = {
  ...baseConfig,
  memoryCache: true,
  historyEnabled: true,
  historySize: 10,
  search: {
    hitDecorators: [
      ...hitDecorators,
      thumbnailDecorator({ size: "8" }) // 400x400
    ]
  },
  queryModifications: pipe<SearchQuery>(withBaseConfig, withAutocompleteDefaults)
} satisfies AutocompleteConfig

function withAutocompleteDefaults(query: SearchQuery) {
  return {
    ...query,
    products: {
      ...query.products,
      size: 8
    },
    keywords: {
      fields: ["keyword", "_highlight.keyword"],
      size: 5,
      facets: ["*"]
    },
    popularSearches: {
      fields: ["query"],
      size: 5
    },
    categories: {
      fields: ["name", "url"],
      size: 5
    }
  } satisfies SearchQuery
}

/**
 * Category page configuration
 */

export const categoryConfig = {
  ...baseConfig,
  persistentSearchCache: false,
  preservePageScroll: false,
  queryModifications: pipe(withBaseConfig, withCategoryMetadata)
} satisfies CategoryConfig

function withCategoryMetadata(query: SearchQuery) {
  return {
    ...query,
    products: {
      categoryId: tagging.categoryId(),
      categoryPath: tagging.categoryPath(),
      ...query.products
    }
  } satisfies SearchQuery
}

/**
 * Search result page (serp) configuration
 */
export const serpConfig = {
  ...baseConfig,
  persistentSearchCache: false,
  preservePageScroll: false
} satisfies SerpConfig
import { Product } from "@/types"
import { SerpElement } from "@nosto/search-js/preact/serp"
import { AutocompleteElement } from "@nosto/search-js/preact/autocomplete"
import { cl } from "@nosto/search-js/utils"
import DynamicCard from "@/elements/DynamicCard/DynamicCard"
import { mockThemeCards } from "@/config"
import styles from "./ThemeProductCard.module.css"

/**
 * Theme sections that render each card type (fetched as /products/{handle}?section_id={section}).
 */
export const cardSections = {
  grid: "api-nosto-product-card",
  "grid-no-quick-view": "api-nosto-product-card-mini",
  list: "api-nosto-product-card-list"
} as const

export type CardType = keyof typeof cardSections

type Props = {
  product: Product
  type?: CardType
  /** Which Nosto click event the card records: search page (default) or autocomplete dropdown */
  context?: "serp" | "autocomplete"
}

/**
 * Product card rendered by the Shopify theme, so markup, styles and quick view match the theme exactly.
 *
 * Usage:
 *   <ThemeProductCard product={hit} />                            // regular card (product-grid-item)
 *   <ThemeProductCard product={hit} type="grid-no-quick-view" />  // product-grid-item with hide_quick_add
 *   <ThemeProductCard product={hit} type="list" />                // list card (upsell-product)
 *   <ThemeProductCard product={hit} context="autocomplete" />     // inside the autocomplete dropdown
 *
 * Grid types go inside the theme grid (`<div class="grid">`). A skeleton styled like the card type holds the
 * card's space until the theme HTML lands (and stands in for skeleton hits, see `skeletonLoading` in config.ts). Keep the Serp/AutocompleteElement wrapper so Nosto tracks product clicks.
 */
export default function ThemeProductCard({ product, type = "grid", context = "serp" }: Props) {
  const Skeleton = type === "list" ? ListSkeleton : GridSkeleton

  if (product.tags1?.includes("skeleton")) {
    return <Skeleton />
  }

  if (!product.handle) {
    return null
  }

  const Element = context === "autocomplete" ? AutocompleteElement : SerpElement

  return (
    <div className={styles.cell}>
      <Element
        as={DynamicCard}
        hit={{
          productId: product.productId!,
          url: product.url
        }}
        componentProps={{
          handle: product.handle,
          section: cardSections[type],
          lazy: true,
          mock: mockThemeCards
        }}
      />
      {!mockThemeCards && <Skeleton />}
    </div>
  )
}

/**
 * Mirrors the markup of product-grid-item.liquid so theme.css gives it the same size as the real card.
 */
function GridSkeleton() {
  return (
    <div
      className={cl("grid-item product-item product-item--left product-item--outer-text", styles.skeleton)}
      aria-hidden="true"
    >
      <div className="product-item__image">
        <div className={cl(styles.shimmer, styles.gridImage)} />
      </div>
      <div className="product-information" style={{ "--swatch-size": "var(--swatch-size-filters)" }}>
        <div className="product-item__info body-medium">
          <div className="product-item__swatches rs-card-swatches">
            <span className="rs-card-swatches__swatch swatches swatch__button swatch__button--circle">
              <span className="sibling__link" />
            </span>
          </div>
          <div className="product-link">
            <p className="product-item__title font-product-title">
              <span className={cl(styles.shimmer, styles.text)}>Product title</span>
            </p>
            <div className="product-item__price__holder body-small">
              <div className="product-item__price">
                <span className={cl(styles.shimmer, styles.text)}>$00.00</span>
              </div>
            </div>
          </div>
          <div className="product-item__timeline rs-card-timeline body-x-small">
            <span className={cl(styles.shimmer, styles.text)}>Ships Immediately</span>
          </div>
        </div>
      </div>
    </div>
  )
}

function ListSkeleton() {
  return (
    <div className={cl("product-upsell__holder", styles.skeleton)} aria-hidden="true">
      <div className="product-upsell">
        <div className="product-upsell__image">
          <div className={cl("product-upsell__image__thumb", styles.shimmer)} />
        </div>
        <div className="product-upsell__content">
          <p className="product-upsell__title font-product-title heading-medium">
            <span className={cl(styles.shimmer, styles.text)}>Product title</span>
          </p>
          <div className="product-upsell__price">
            <span className={cl(styles.shimmer, styles.text)}>$00.00</span>
          </div>
        </div>
      </div>
    </div>
