import { useNostoAppState, useResponse } from "@nosto/search-js/preact/hooks"
import { AutocompleteElement } from "@nosto/search-js/preact/autocomplete"
import { SearchCategory, SearchKeyword, SearchPopularSearch } from "@nosto/nosto-js/client"
import { ComponentChildren } from "preact"
import { cl } from "@nosto/search-js/utils"
import ThemeProductCard from "@/components/Product/ThemeProductCard"
import { useRovingFocus } from "@/hooks/useRovingFocus"
import { searchPath } from "@/config"
import { QUERY_PARAM } from "@/mapping/url/constants"
import { useOnSubmit } from "./OnSubmitContext"
import { useLayoutEffect, useRef } from "preact/hooks"

type Props = {
  onKeyDown: (e: KeyboardEvent) => void
}

/**
 * Autocomplete dropdown using the theme's predictive search markup (sections/predictive-search.liquid),
 * so predictive-search.css styles it. Products are theme cards without quick view.
 */
export default function ThemeResults({ onKeyDown }: Props) {
  const { keywords, categories, popularSearches, products } = useResponse()
  const query = useNostoAppState(state => state.query?.query)
  const containerRef = useRovingFocus<HTMLDivElement>(".ns-autocomplete-element")

  const keywordHits = keywords?.hits ?? []
  const categoryHits = categories?.hits ?? []
  const popularSearchHits = popularSearches?.hits ?? []
  const productHits = products?.hits ?? []
  const visible = !!query && [keywordHits, categoryHits, popularSearchHits, productHits].some(hits => hits.length > 0)
  const resultsRef = useResultsHeight(visible)

  if (!visible) {
    return null
  }

  return (
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions
    <div
      ref={resultsRef}
      className="predictive-search"
      data-nosto-element="autocomplete"
      data-scroll-lock-scrollable
      onKeyDown={onKeyDown}
    >
      <div className="wrapper--full-padded" ref={containerRef}>
        <div
          className={cl("predictive-search__layout", !productHits.length && "predictive-search__layout--no-products")}
        >
          <div className="predictive-search__column">
            {keywordHits.length > 0 && (
              <Group heading="Suggestions">
                {keywordHits.map(keyword => (
                  <Keyword key={keyword.keyword} keyword={keyword} />
                ))}
              </Group>
            )}
            {categoryHits.length > 0 && (
              <Group heading="Collections">
                {categoryHits.map(category => (
                  <Category key={category.url} category={category} />
                ))}
              </Group>
            )}
            {popularSearchHits.length > 0 && (
              <Group heading="Popular searches">
                {popularSearchHits.map(search => (
                  <PopularSearch key={search.query} search={search} />
                ))}
              </Group>
            )}
            <div className="predictive-search__actions">
              <button type="submit" className="btn btn--outline btn--primary">
                Search for &quot;{query}&quot;
              </button>
            </div>
          </div>
          {productHits.length > 0 && (
            <div className="predictive-search__column">
              <div className="predictive-search__group">
                <p className="predictive-search__heading body-small">Products</p>
                <div className="predictive-search__products__list grid-outer">
                  <div className="grid">
                    {productHits.map(hit => (
                      <ThemeProductCard
                        key={hit.productId}
                        product={hit}
                        type="grid-no-quick-view"
                        context="autocomplete"
                      />
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

/**
 * Caps the dropdown at the visible viewport so it scrolls, like PredictiveSearch.open() in theme.dev.js.
 */
function useResultsHeight(visible: boolean) {
  const ref = useRef<HTMLDivElement>(null)

  useLayoutEffect(() => {
    const element = ref.current
    if (!visible || !element) return

    function update() {
      const viewportHeight = window.visualViewport?.height ?? window.innerHeight
      element!.style.setProperty("--results-height", `${viewportHeight - element!.getBoundingClientRect().top}px`)
    }

    update()
    window.addEventListener("resize", update)
    return () => window.removeEventListener("resize", update)
  }, [visible])

  return ref
}

function Keyword({ keyword }: { keyword: SearchKeyword }) {
  const onSubmit = useOnSubmit()

  function onClick(e: Event) {
    e.preventDefault()
    if (keyword._redirect) {
      window.location.href = keyword._redirect
    } else {
      onSubmit(keyword.keyword, { isKeyword: true })
    }
  }

  return (
    <div className="predictive-search__item">
      <AutocompleteElement
        hit={keyword}
        as="a"
        componentProps={{
          className: "predictive-search__link",
          href: searchUrl(keyword.keyword),
          onClick
        }}
      >
        {keyword._highlight?.keyword ? (
          <span dangerouslySetInnerHTML={{ __html: keyword._highlight.keyword }} />
        ) : (
          keyword.keyword
        )}
      </AutocompleteElement>
    </div>
  )
}

function Group({ heading, children }: { heading: string; children: ComponentChildren }) {
  return (
    <div className="predictive-search__group">
      <p className="predictive-search__heading body-small">{heading}</p>
      {children}
    </div>
  )
}

function Category({ category }: { category: SearchCategory }) {
  return (
    <div className="predictive-search__item">
      <AutocompleteElement
        hit={category}
        as="a"
        componentProps={{ className: "predictive-search__link", href: category.url }}
      >
        {category.fullName ?? category.name}
      </AutocompleteElement>
    </div>
  )
}

function PopularSearch({ search }: { search: SearchPopularSearch }) {
  const onSubmit = useOnSubmit()
  const query = search.query!

  function onClick(e: Event) {
    e.preventDefault()
    onSubmit(query, { isPopular: true })
  }

  return (
    <div className="predictive-search__item">
      <AutocompleteElement
        hit={{ keyword: query }}
        as="a"
        componentProps={{ className: "predictive-search__link", href: searchUrl(query), onClick }}
      >
        {query}
      </AutocompleteElement>
    </div>
  )
}

function searchUrl(query: string) {
  return `${searchPath}?${QUERY_PARAM}=${encodeURIComponent(query)}`
}
import ThemeResults from "./ThemeResults"
import { useDomEvents } from "@/hooks/useDomEvents"
import { usePopState } from "@/hooks/usePopState"
import { selectors } from "@/config"
import { useAutocomplete } from "./useAutocomplete"
import { SearchAnalyticsOptions } from "@nosto/nosto-js/client"
import { OnSubmitProvider } from "./OnSubmitContext"
import { useRef, useEffect } from "preact/hooks"
import { useNostoAppState } from "@nosto/search-js/preact/hooks"
import { QUERY_PARAM } from "@/mapping/url/constants"

type Props = {
  dropdown: HTMLElement
  onSubmit: (input: string, options?: SearchAnalyticsOptions) => void
}

/**
 * Binds to the search input and form that contain `dropdown`, so every header search popdown gets its own instance.
 */
export default function AutocompleteInjected({ dropdown, onSubmit }: Props) {
  const dropdownRef = useRef<HTMLElement | null>(null)
  const searchInputRef = useRef<HTMLInputElement | null>(null)
  const searchFormRef = useRef<HTMLFormElement | null>(null)

  useEffect(() => {
    const form = dropdown.closest<HTMLFormElement>(selectors.searchForm)
    dropdownRef.current = dropdown
    searchInputRef.current = form?.querySelector<HTMLInputElement>(selectors.searchInput) ?? null
    searchFormRef.current = form
  }, [dropdown])

  const redirect = useNostoAppState(state => state.response?.redirect)

  const { input, showAutocomplete, setInput, setShowAutocomplete, onSearchSubmit, onKeyDown } = useAutocomplete({
    onSubmit,
    searchInputRef,
    clickOutsideTargetRef: dropdownRef,
    isInjected: true
  })

  usePopState(() => {
    const searchParams = new URLSearchParams(window.location.search)
    const query = searchParams.get(QUERY_PARAM) || ""
    if (searchInputRef.current && query) {
      searchInputRef.current.value = query
    }
  })

  useDomEvents(searchInputRef, {
    onInput: () => setInput(searchInputRef.current?.value || ""),
    onFocus: () => setShowAutocomplete(true),
    onKeyDown
  })

  useDomEvents(searchFormRef, {
    onSubmit: e => {
      e.preventDefault()
      if (redirect) {
        // Direct navigation is intentional for redirect rules (can be external URLs)
        window.location.href = redirect
      } else {
        onSearchSubmit(input)
      }
    }
  })

  return showAutocomplete ? (
    <OnSubmitProvider onSubmit={onSearchSubmit}>
      <ThemeResults onKeyDown={onKeyDown} />
    </OnSubmitProvider>
  ) : null
}
import { SearchPageProvider } from "@nosto/search-js/preact/serp"
import { AutocompletePageProvider } from "@nosto/search-js/preact/autocomplete"
import { createPortal, render, useCallback, useState } from "preact/compat"
import Serp from "@/components/Serp/Serp"
import "@/variables.css"
import "@/theme-bridge.css"
import "@nosto/web-components"
import SearchQueryHandler from "@/components/SearchQueryHandler/SearchQueryHandler"
import { SidebarProvider } from "@/contexts/SidebarContext"
import { autocompleteConfig, categoryConfig, redirectOnSearch, searchPath, selectors, serpConfig } from "@/config"
import { useActions } from "@nosto/search-js/preact/hooks"
import Category from "@/components/Category/Category"
import { CategoryPageProvider } from "@nosto/search-js/preact/category"
import { tagging } from "@/mapping/tagging"
import { nostojs } from "@nosto/nosto-js"
import { ErrorBoundary } from "@nosto/search-js/preact/common"
import Portal from "@/elements/Portal/Portal"
import AutocompleteInjected from "@/components/Autocomplete/AutocompleteInjected"
import { PageType, SearchAnalyticsOptions } from "@nosto/nosto-js/client"
import { searchNavigate } from "./searchNavigate"
import { usePopState } from "@/hooks/usePopState"
import { QUERY_PARAM } from "@/mapping/url/constants"

type AutocompleteProps = {
  onSubmit: (query: string, options?: SearchAnalyticsOptions) => void
}

function Autocomplete({ onSubmit }: AutocompleteProps) {
  const handleSubmit = useCallback(
    (query: string, options?: SearchAnalyticsOptions) => {
      const trimmedQuery = query.trim()
      if (!trimmedQuery) {
        return
      }
      nostojs(api => api.recordSearchSubmit(trimmedQuery))
      onSubmit(trimmedQuery, options)
    },
    [onSubmit]
  )

  // One autocomplete per header search popdown (desktop, mobile, mobile menu)
  const [dropdowns] = useState(() => Array.from(document.querySelectorAll<HTMLElement>(selectors.dropdown)))

  return (
    <>
      {dropdowns.map((dropdown, index) => (
        <AutocompletePageProvider config={autocompleteConfig} key={index}>
          {createPortal(<AutocompleteInjected dropdown={dropdown} onSubmit={handleSubmit} />, dropdown)}
        </AutocompletePageProvider>
      ))}
    </>
  )
}

type AppProps = {
  onSearch: (query: string, options?: SearchAnalyticsOptions) => void
}

function SerpApp() {
  const { newSearch } = useActions()

  return (
    <ErrorBoundary>
      <SearchQueryHandler />
      <SidebarProvider>
        <Autocomplete onSubmit={(query, options) => newSearch({ query }, options)} />
        <Portal target={selectors.results} clear>
          <Serp />
        </Portal>
      </SidebarProvider>
    </ErrorBoundary>
  )
}

function CategoryApp({ onSearch }: AppProps) {
  return (
    <ErrorBoundary>
      <SearchQueryHandler />
      <SidebarProvider>
        <Autocomplete onSubmit={onSearch} />
        <Portal target={selectors.results} clear>
          <Category />
        </Portal>
      </SidebarProvider>
    </ErrorBoundary>
  )
}

function DefaultApp({ onSearch }: AppProps) {
  return (
    <ErrorBoundary>
      <Autocomplete onSubmit={onSearch} />
    </ErrorBoundary>
  )
}

function setTaggingPageType(pageType: PageType | undefined) {
  nostojs(api => api.setTaggingProvider("pageType", pageType))
}

function App() {
  const [pageType, setPageType] = useState(() => tagging.pageType())

  function onSearch(query: string) {
    if (redirectOnSearch) {
      searchNavigate(query)
    } else {
      searchNavigate(query, "history")
      setPageType("search")
      setTaggingPageType("search")
    }
  }

  usePopState(() => {
    if (redirectOnSearch) return
    const isSearchPage = location.pathname === searchPath
    const pageType = isSearchPage ? "search" : tagging.pageType()
    setPageType(pageType)
    setTaggingPageType(pageType)
  }, [setPageType])

  switch (pageType) {
    case "category":
      return (
        <CategoryPageProvider config={categoryConfig}>
          <CategoryApp onSearch={onSearch} />
        </CategoryPageProvider>
      )
    case "search":
      return (
        <SearchPageProvider config={serpConfig}>
          <SerpApp />
        </SearchPageProvider>
      )
    default:
      return <DefaultApp onSearch={onSearch} />
  }
}

function searchTermsProvider() {
  const params = new URLSearchParams(window.location.search)
  const searchParams = params.get(QUERY_PARAM)
  return searchParams ? [searchParams] : []
}

async function init() {
  const api = await new Promise(nostojs)
  // wait for tagging to be available
  await api.pageTaggingAsync()
  const dummy = document.createElement("div")
  nostojs(api => api.setTaggingProvider("searchTerms", searchTermsProvider))
  render(<App />, dummy)
}
init()

