/**
 * Theme copy, so the Nosto UI shows the same translated strings as the Liquid search page.
 * The theme renders it as JSON in `[data-nosto-i18n]` (snippets/nosto-i18n.liquid in Elie_Tahari_TAHARI_2026).
 * Fallbacks are the theme's en.default.json values, used on the dev page and if the JSON is missing.
 */
const defaults = {
  resultsOne: '{count} result found for "{terms}"',
  resultsOther: '{count} results found for "{terms}"',
  noResults: 'No results found for "{terms}". Check the spelling or use a different word or phrase.',
  noMatches: "Sorry, there are no products here.",
  filters: "Filters",
  sort: "Sort",
  prev: "Previous",
  next: "Next",
  products: "Products",
  suggestions: "Suggestions",
  searchFor: 'Search for "{terms}"',
  /** Shopify sort option labels keyed by sort value (relevance, price-ascending, ...) */
  sortOptions: {} as Record<string, string>
}

export type Strings = typeof defaults

let cached: Strings | undefined

export function strings(): Strings {
  if (!cached) {
    cached = { ...defaults, ...readThemeStrings() }
  }
  return cached
}

function readThemeStrings(): Partial<Strings> {
  const json = document.querySelector("[data-nosto-i18n]")?.textContent
  if (!json) return {}
  try {
    return JSON.parse(json) as Partial<Strings>
  } catch {
    return {}
  }
}

/** Replaces `{name}` placeholders, e.g. format(strings().searchFor, { terms: "dress" }) */
export function format(template: string, values: Record<string, string | number>) {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? String(values[key]) : match))
}

/** Test hook: forget the parsed strings so the next call re-reads the DOM */
export function resetStrings() {
  cached = undefined
}

