import { usePagination, useActions, Page } from "@nosto/search-js/preact/hooks"
import { getPageUrl } from "@/mapping/url/getPageUrl"
import ThemeIcon from "@/elements/ThemeIcon/ThemeIcon"

/**
 * Pagination using the theme's markup (snippets/pagination.liquid), so pagination-custom.css styles it.
 */
export default function Pagination() {
  const { prev, first, pages, last, next } = usePagination({
    width: 5
  })

  const { updateSearch } = useActions()

  if (pages.length <= 1) {
    return null
  }

  function pageLinkProps({ from, page }: Page) {
    return {
      href: getPageUrl(page),
      onClick: (e: Event) => {
        e.preventDefault()
        updateSearch({ products: { from } })
        scrollTo(0, 0)
      }
    }
  }

  return (
    <nav aria-label="Pagination" className="pagination-custom">
      {prev ? (
        <a className="pagination-custom__prev" title="Previous" aria-label="Previous page" {...pageLinkProps(prev)}>
          <span>Previous</span>
          <ThemeIcon name="nav-arrow-left" />
        </a>
      ) : (
        <span className="pagination-custom__prev is-hidden">
          <span>Previous</span>
          <ThemeIcon name="nav-arrow-left" />
        </span>
      )}

      <div className="pagination-custom__inner">
        {first && (
          <>
            <a className="pagination-custom__page" aria-label="First page" {...pageLinkProps(first)}>
              {first.page}
            </a>
            <span className="pagination-custom__sep">…</span>
          </>
        )}

        {pages.map(page =>
          page.current ? (
            <span key={page.page} className="pagination-custom__page pagination-custom__page--active">
              {page.page}
            </span>
          ) : (
            <a
              key={page.page}
              className="pagination-custom__page"
              aria-label={`${page.page} page`}
              {...pageLinkProps(page)}
            >
              {page.page}
            </a>
          )
        )}

        {last && (
          <>
            <span className="pagination-custom__sep">…</span>
            <a className="pagination-custom__page" aria-label="Last page" {...pageLinkProps(last)}>
              {last.page}
            </a>
          </>
        )}
      </div>

      {next ? (
        <a className="pagination-custom__next" title="Next" aria-label="Next page" {...pageLinkProps(next)}>
          <span>Next</span>
          <ThemeIcon name="nav-arrow-right" />
        </a>
      ) : (
        <span className="pagination-custom__next is-hidden">
          <span>Next</span>
          <ThemeIcon name="nav-arrow-right" />
        </span>
      )}
    </nav>
  )
}
import { useNostoAppState } from "@nosto/search-js/preact/hooks"

/**
 * No-results state using the theme's markup (sections/search.liquid).
 */
export default function NoResults() {
  const query = useNostoAppState(state => state.response.query)

  return (
