import { getPageUrl } from "@/mapping/url/getPageUrl"
import ThemeIcon from "@/elements/ThemeIcon/ThemeIcon"

/**
 * Pagination using the theme's markup (snippets/pagination.liquid), so pagination-custom.css styles it.
 */
export default function Pagination() {
  const { prev, first, pages, last, next } = usePagination({
    width: 5
  })

  const { updateSearch } = useActions()

  if (pages.length <= 1) {
    return null
  }

  function pageLinkProps({ from, page }: Page) {
    return {
      href: getPageUrl(page),
      onClick: (e: Event) => {
        e.preventDefault()
        updateSearch({ products: { from } })
        scrollTo(0, 0)
      }
    }
  }

  return (
    <nav aria-label="Pagination" className="pagination-custom">
      {prev ? (
        <a className="pagination-custom__prev" title="Previous" aria-label="Previous page" {...pageLinkProps(prev)}>
          <span>Previous</span>
          <ThemeIcon name="nav-arrow-left" />
        </a>
      ) : (
        <span className="pagination-custom__prev is-hidden">
          <span>Previous</span>
          <ThemeIcon name="nav-arrow-left" />
