          <>
            <a className="pagination-custom__page" aria-label="First page" {...pageLinkProps(first)}>
              {first.page}
            </a>
            <span className="pagination-custom__sep">…</span>
          </>
        )}

        {pages.map(page =>
          page.current ? (
            <span key={page.page} className="pagination-custom__page pagination-custom__page--active">
              {page.page}
