import { selectors } from "@/config"

/**
 * Search section settings the theme passes on the results mount (sections/search.liquid in
 * Elie_Tahari_TAHARI_2026), since Nosto can't read Liquid section settings itself.
 * Defaults match templates/search.json and apply on the dev page.
 */
export function mountSettings() {
  const mount = document.querySelector<HTMLElement>(selectors.results)
  const data = mount?.dataset ?? {}

  return {
    cardImageMode: data.cardImageMode === "product" ? "product" : "model",
    filterLayout: data.filterLayout ?? "slide-out",
    enableSort: data.enableSort !== "false",
    enableFilters: data.enableFilters !== "false"
  } as const
}

import { useLayoutEffect, useRef } from "preact/hooks"

/**
 * The theme's Model | Product switcher (snippets/collection-model-switcher.liquid), cloned from the
 * `<template data-nosto-model-switcher>` the search section renders. Cloning parsed HTML lets the theme's
 * <collection-model-switcher> custom element upgrade normally; it must not be rendered through JSX.
 * Its script (collection-model-switcher.js) swaps card images, including cards Nosto adds later.
 */
export default function ThemeModelSwitcher() {
  const ref = useRef<HTMLSpanElement>(null)

  useLayoutEffect(() => {
    const template = document.querySelector<HTMLTemplateElement>("template[data-nosto-model-switcher]")
    const container = ref.current
    if (!template || !container) return
    container.replaceChildren(template.content.cloneNode(true))
  }, [])

  return <span ref={ref} style={{ display: "contents" }} />
}

