input.command:
python3 -I - <<'EOF'
import pathlib
p=pathlib.Path('src/components/Autocomplete/ThemeResults.tsx'); s=p.read_text()
start=s.index('/**\n * Autocomplete dropdown')
end=s.index('/**\n * Caps the dropdown')
new='''/**
 * Autocomplete dropdown using the theme's predictive search markup (sections/predictive-search.liquid),
 * so predictive-search.css styles it: query and collection suggestions in one "Suggestions" group, the
 * "Search for" button, and products as the theme's search-product-item card. Products only, no pages or
 * articles (decided 2026-10-05).
 */
export default function ThemeResults({ onKeyDown }: Props) {
  const { keywords, categories, products } = useResponse()
  const query = useNostoAppState(state => state.query?.query)
  const containerRef = useRovingFocus<HTMLDivElement>(".ns-autocomplete-element")
  const text = strings()

  const keywordHits = keywords?.hits ?? []
  const categoryHits = categories?.hits ?? []
  const productHits = products?.hits ?? []
  const hasSuggestions = keywordHits.length > 0 || categoryHits.length > 0
  const visible = !!query && (hasSuggestions || productHits.length > 0)
  const resultsRef = useResultsHeight(visible)

  if (!visible) {
    return null
  }

  const searchFor = (
    <button type="submit" className="predictive-search__actions-button">
      <span>{format(text.searchFor, { terms: query })}</span>
    </button>
  )

  return (
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions
    <div
      ref={resultsRef}
      className="predictive-search"
      data-nosto-element="autocomplete"
      data-scroll-lock-scrollable
      onKeyDown={onKeyDown}
    >
      <div className="wrapper" ref={containerRef}>
        <div role="listbox">
          <div
            className={cl(
              "predictive-search__layout",
              !productHits.length && "predictive-search__layout--no-products",
              !hasSuggestions && "predictive-search__layout--no-suggestions"
            )}
          >
            {hasSuggestions && (
              <div className="predictive-search__column">
                <div className="predictive-search__group">
                  <p className="predictive-search__heading">{text.suggestions}</p>
                  {keywordHits.map(keyword => (
                    <Keyword key={keyword.keyword} keyword={keyword} />
                  ))}
                  {categoryHits.map(category => (
                    <Category key={category.url} category={category} />
                  ))}
                </div>
                <div className="predictive-search__actions within-group">{searchFor}</div>
              </div>
            )}
            {productHits.length > 0 && (
              <div className="predictive-search__column">
                <div className="predictive-search__group">
                  <p className="predictive-search__heading">{text.products}</p>
                  <div className="predictive-search__products__list grid-outer">
                    <div className="grid">
                      {productHits.map(hit => (
                        <ThemeProductCard key={hit.productId} product={hit} type="mini" context="autocomplete" />
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
          {!hasSuggestions && <div className="predictive-search__actions">{searchFor}</div>}
        </div>
      </div>
    </div>
  )
}

'''
s=s[:start]+new+s[end:]
# drop Group and PopularSearch helpers
gs=s.index('function Group(')
ge=s.index('function Category(')
s=s[:gs]+s[ge:]
ps=s.index('function PopularSearch(')
pe=s.index('function searchUrl(')
s=s[:ps]+s[pe:]
s=s.replace('import { SearchCategory, SearchKeyword, SearchPopularSearch } from "@nosto/nosto-js/client"\nimport { ComponentChildren } from "preact"\n','import { SearchCategory, SearchKeyword } from "@nosto/nosto-js/client"\n')
s=s.replace('import { useLayoutEffect, useRef } from "preact/hooks"\n','import { useLayoutEffect, useRef } from "preact/hooks"\nimport { format, strings } from "@/i18n"\n')
p.write_text(s)
EOF
