H=$(curl -s -A 'Mozilla/5.0' 'https://www.elietahari.com/collections/all/products.json?limit=1' | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>console.log(JSON.parse(s).products[0].handle))'); echo $H; curl -s -A 'Mozilla/5.0' "https://www.elietahari.com/products/$H?section_id=api-product-grid-item" -o /private/tmp/claude-501/card.html; node -e '
const h=require("fs").readFileSync("/private/tmp/claude-501/card.html","utf8");
// print tag skeleton: opening tags with class attr, indentation by depth, skip svg internals, collapse
const re=/<(\/?)([a-z0-9-]+)([^>]*)>/gi; let d=0,m,out=[];
const voids=new Set(["img","input","br","source","meta","link","path","circle","rect","line","polyline"]);
while((m=re.exec(h))){const [_,cl,tag,attrs]=m; if(cl){d--;continue;} const c=(attrs.match(/class="([^"]*)"/)||[])[1]; const da=(attrs.match(/ (data-[a-z-]+)/g)||[]).join(""); if(!["svg","path","source","script","style"].includes(tag)) out.push("  ".repeat(Math.max(d,0))+tag+(c?"."+c.trim().replace(/\s+/g,"."):"")+da.slice(0,80)); if(!voids.has(tag)&&!attrs.endsWith("/")) d++;}
console.log(out.slice(0,90).join("\n"))'

