input.function:
() => {
  const root = document.querySelector('[data-grid-item]') || document.body.firstElementChild;
  const out = [];
  const walk = (el, d) => {
    if (['SVG', 'svg', 'SCRIPT', 'STYLE', 'TEMPLATE', 'PATH', 'path', 'SOURCE'].includes(el.tagName)) return;
    const data = [...el.attributes].filter(a => a.name.startsWith('data-')).map(a => a.name).join(' ');
    const style = el.getAttribute('style') ? ' style=' + el.getAttribute('style').slice(0, 60) : '';
    out.push('  '.repeat(d) + el.tagName.toLowerCase() + (el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\s+/).join('.') : '') + (data ? ' [' + data.slice(0, 90) + ']' : '') + style);
    if (d < 9) [...el.children].forEach(c => walk(c, d + 1));
  };
  walk(root, 0);
  return out.slice(0, 110).join('\n');
}

