import { Product } from "@/types"
import { SerpElement } from "@nosto/search-js/preact/serp"
import { AutocompleteElement } from "@nosto/search-js/preact/autocomplete"
import { cl } from "@nosto/search-js/utils"
import DynamicCard from "@/elements/DynamicCard/DynamicCard"
import { mockThemeCards } from "@/config"
import styles from "./ThemeProductCard.module.css"

/**
 * Theme sections that render each card type (fetched as /products/{handle}?section_id={section}).
 * Both live in Elie_Tahari_TAHARI_2026.
 */
export const cardSections = {
  /** product-grid-item.liquid: the search results card */
  grid: "api-nosto-product-card",
  /** search-product-item.liquid: the predictive search dropdown card */
  mini: "api-nosto-product-card-mini"
} as const

export type CardType = keyof typeof cardSections

type Props = {
  product: Product
  type?: CardType
  /** Which Nosto click event the card records: search page (default) or autocomplete dropdown */
  context?: "serp" | "autocomplete"
}

/**
 * Product card rendered by the Shopify theme, so markup, styles, badges, swatches and quick add match the
 * theme exactly. See docs/product-card/spec.md for what the card shows.
 *
 * Usage:
 *   <ThemeProductCard product={hit} />                                   // search results grid card
 *   <ThemeProductCard product={hit} type="mini" context="autocomplete" /> // autocomplete dropdown card
 *
 * A skeleton shaped like the card holds its space until the theme HTML lands (and stands in for skeleton
 * hits, see `skeletonLoading` in config.ts). Keep the Serp/AutocompleteElement wrapper so Nosto tracks clicks.
 */
export default function ThemeProductCard({ product, type = "grid", context = "serp" }: Props) {
  const Skeleton = type === "mini" ? MiniSkeleton : GridSkeleton

  if (product.tags1?.includes("skeleton")) {
    return <Skeleton />
  }

  if (!product.handle) {
    return null
  }

  const Element = context === "autocomplete" ? AutocompleteElement : SerpElement

  return (
    <div className={styles.cell}>
      <Element
        as={DynamicCard}
        hit={{
          productId: product.productId!,
          url: product.url
        }}
        componentProps={{
          handle: product.handle,
          section: cardSections[type],
          lazy: true,
          mock: mockThemeCards
        }}
      />
      {!mockThemeCards && <Skeleton />}
    </div>
  )
}

/**
 * Mirrors the outer markup of product-grid-item.liquid so theme.css sizes it like the real card:
 * the image box takes the theme's ratio, then title, price and color count lines.
 */
function GridSkeleton() {
  return (
    <div
      className={cl("grid-item product-item product-item--left product-item--outer-text", styles.skeleton)}
      aria-hidden="true"
    >
      <div className="product-item__image">
        <div className={cl(styles.shimmer, styles.gridImage)} />
      </div>
      <div className="product-information">
        <div className="product-item__info body-medium">
          <p className="product-item__title">
            <span className={cl(styles.shimmer, styles.text)}>Product title</span>
          </p>
          <div className="product-item__price__holder">
            <div className="product-item__price">
              <span className={cl(styles.shimmer, styles.text)}>$000</span>
            </div>
          </div>
          <span className="product-item__swatches__count">
            <span className={cl(styles.shimmer, styles.text)}>1 color</span>
          </span>
        </div>
      </div>
    </div>
  )
}

/**
 * Mirrors search-product-item.liquid (the predictive search card).
 */
function MiniSkeleton() {
  return (
    <div
      className={cl(
        "predictive-search__grid-item product-item grid-item product-item--left product-item--outer-text",
        styles.skeleton
      )}
      aria-hidden="true"
    >
      <div className="product-item__image">
        <div className={cl(styles.shimmer, styles.gridImage)} />
      </div>
      <div className="product-information">
        <div className="product-item__info">
          <p className="product-item__title">
            <span className={cl(styles.shimmer, styles.text)}>Product title</span>
          </p>
          <span className={cl(styles.shimmer, styles.text)}>$000</span>
        </div>
      </div>
    </div>
  )
}

