import { afterEach, describe, expect, it } from "vitest"
import { format, resetStrings, strings } from "@/i18n"

function addThemeStrings(json: string) {
  const script = document.createElement("script")
  script.type = "application/json"
  script.setAttribute("data-nosto-i18n", "")
  script.textContent = json
  document.body.appendChild(script)
}

describe("i18n", () => {
  afterEach(() => {
    document.querySelectorAll("[data-nosto-i18n]").forEach(el => el.remove())
    resetStrings()
  })

  it("falls back to the theme's English copy without theme JSON", () => {
    expect(strings().filters).toBe("Filters")
  })

  it("reads translated copy from the theme", () => {
    addThemeStrings(JSON.stringify({ filters: "Filtres", sortOptions: { relevance: "Pertinence" } }))
    expect(strings().filters).toBe("Filtres")
    expect(strings().sortOptions.relevance).toBe("Pertinence")
    expect(strings().next).toBe("Next")
  })

  it("picks up theme JSON that appears after a first read", () => {
    expect(strings().filters).toBe("Filters")
    addThemeStrings(JSON.stringify({ filters: "Filter" }))
    expect(strings().filters).toBe("Filter")
  })

  it("ignores invalid theme JSON", () => {
    addThemeStrings("{not json")
    expect(strings().filters).toBe("Filters")
  })

  it("fills placeholders", () => {
    expect(format('{count} results found for "{terms}"', { count: 3, terms: "dress" })).toBe(
      '3 results found for "dress"'
    )
    expect(format("{missing}", {})).toBe("{missing}")
  })
})

