input.function:
async () => {
  const mount = document.querySelector('[data-nosto-search]');
  return {
    themeId: Shopify.theme.id, themeName: Shopify.theme.name,
    mount: !!mount, mountAttrs: mount ? Object.assign({}, mount.dataset) : null,
    gridWrapper: !!mount?.closest('[data-products-grid]'),
    collectionComponent: !!mount?.closest('collection-component'),
    switcherTemplate: !!document.querySelector('template[data-nosto-model-switcher]'),
    i18nCount: document.querySelectorAll('[data-nosto-i18n]').length,
    i18n: (() => { try { return JSON.parse(document.querySelector('[data-nosto-i18n]').textContent) } catch (e) { return 'ERR ' + e.message } })(),
    autocompleteMounts: document.querySelectorAll('[data-nosto-autocomplete]').length,
    predictiveSearchEl: document.querySelectorAll('predictive-search').length,
    nostojs: typeof window.nostojs, nostoScripts: [...document.scripts].map(s => s.src).filter(s => /nosto/i.test(s)).slice(0, 5),
    liquidResults: !!document.querySelector('#SearchLoop')
  };
}

