input.function:
async () => {
  const html = await fetch(location.pathname + location.search, { cache: 'no-store' }).then(r => r.text());
  const i = html.indexOf('data-nosto-autocomplete');
  const errs = [...html.matchAll(/Liquid error[^<]{0,200}/g)].map(m => m[0]).slice(0, 5);
  return { errs, around: html.slice(Math.max(0, i - 400), i + 40) };
}

