input.function:
async () => {
  const handles = ['camille-sculpt-dress', 'bria-silk-lace-slip-dress-in-bitter-chocolate', 'alix-lace-trenchcoat-in-black-onyx'];
  const out = [];
  for (const h of handles) {
    for (const section of ['api-nosto-product-card', 'api-nosto-product-card-mini']) {
      const r = await fetch(`/products/${h}?section_id=${section}`, { cache: 'no-store' });
      const html = await r.text();
      const doc = new DOMParser().parseFromString(html, 'text/html');
      const inner = doc.body.firstElementChild;
      out.push({
        h: h.slice(0, 24), section, status: r.status, kb: Math.round(html.length / 1024),
        liquidErr: (html.match(/Liquid error[^<]{0,120}/) || [])[0],
        placeholders: (html.match(/\|\|[a-zA-Z]+\|\|/g) || []).length,
        wrapper: inner?.id?.slice(0, 40),
        card: inner?.querySelector('[data-grid-item], .predictive-search__grid-item')?.className.slice(0, 70),
        quickAdd: !!inner?.querySelector('quick-add-product'),
        imgLoading: inner?.querySelector('img')?.getAttribute('loading'),
        fetchpriority: inner?.querySelector('img')?.getAttribute('fetchpriority'),
        sizes: inner?.querySelector('img')?.getAttribute('sizes')?.slice(0, 50),
        aosAnchor: inner?.querySelector('[data-aos-anchor]')?.getAttribute('data-aos-anchor')
      });
    }
  }
  return out;
}

