input.code:
async (page) => {
  const p = await page.context().newPage();
  try {
    await p.goto('https://www.baublebar.com/', { waitUntil: 'domcontentloaded' });
    await p.waitForFunction(() => typeof window.nostojs === 'function', null, { timeout: 15000 });
    return await p.evaluate(() => new Promise(res => nostojs(api => {
      const s = api.internal?.getSettings?.() || {};
      res({ keys: Object.keys(s).length, searchKeys: Object.entries(s).filter(([k]) => /search|template|webComponent/i.test(k)).map(([k, v]) => [k, typeof v === 'object' ? JSON.stringify(v).slice(0, 80) : v]) });
    })));
  } finally { await p.close(); }
}

