22	export type Strings = typeof defaults
23	
24	let cached: Strings | undefined
25	
26	export function strings(): Strings {
27	  if (cached) return cached
28	  const theme = readThemeStrings()
29	  const merged = { ...defaults, ...theme }
30	  // Only cache a successful read: before the theme markup is parsed the JSON isn't there yet
31	  if (theme) cached = merged
32	  return merged
33	}
34	
35	function readThemeStrings(): Partial<Strings> | undefined {
36	  const json = document.querySelector("[data-nosto-i18n]")?.textContent
37	  if (!json) return undefined
38	  try {
39	    return JSON.parse(json) as Partial<Strings>
40	  } catch {
41	    return undefined
42	  }
43	}
