45	/** Replaces `{name}` placeholders, e.g. format(strings().searchFor, { terms: "dress" }) */
46	export function format(template: string, values: Record<string, string | number>) {
47	  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? String(values[key]) : match))
