input.command:
F=/Users/pk/.claude/projects/-Users-pk-Documents-roswell-studios-Elie-Tahari-TAHARI-Nosto/0fb60a1e-3415-46ce-bee4-8f5e04965906.jsonl
node -e '
const fs=require("fs");
const lines=fs.readFileSync(process.argv[1],"utf8").trim().split("\n");
let chars=0, byType={}, tools=0, biggest=[];
for (const l of lines){ let o; try{o=JSON.parse(l)}catch(e){continue}
  const t=o.type||"?"; byType[t]=(byType[t]||0)+1;
  const s=JSON.stringify(o.message||o); chars+=s.length;
  if (o.message?.content) for (const c of [].concat(o.message.content)) { if (c.type==="tool_result"||c.type==="tool_use") tools++; }
  biggest.push([s.length, t]);
}
biggest.sort((a,b)=>b[0]-a[0]);
console.log("events:", lines.length);
console.log("by type:", JSON.stringify(byType));
console.log("tool_use/result blocks:", tools);
console.log("total chars:", chars.toLocaleString(), "~tokens:", Math.round(chars/4).toLocaleString());
console.log("largest events:", biggest.slice(0,5).map(b=>Math.round(b[0]/1000)+"k "+b[1]).join(", "));
' $F

