input.command:
cd ~/Documents/roswell-studios/Elie_Tahari_TAHARI_Nosto && node -e '
const fs=require("fs"); const p=JSON.parse(fs.readFileSync("package.json","utf8"));
p.name="elie-tahari-nosto";
p.description="Nosto Search Templates for Elie Tahari (Shopify)";
p.repository={type:"git",url:"git+https://github.com/roswell-studios/Elie_Tahari_TAHARI_Nosto.git"};
fs.writeFileSync("package.json",JSON.stringify(p,null,2)+"\n");
console.log("scripts:",Object.keys(p.scripts).join(" "));'
sed -i '' 's|<title>BaubleBar Nosto (local dev)</title>|<title>Elie Tahari Nosto (local dev)</title>|' index.html
grep -n title index.html; git diff --stat | cat

