import { useNostoAppState } from "@nosto/search-js/preact/hooks"

/**
 * No-results state using the theme's markup (sections/search.liquid).
 */
export default function NoResults() {
  const query = useNostoAppState(state => state.response.query)

  return (
    <>
      <p className="search__caption caps">
        No results found for &quot;{query}&quot;. Check the spelling or use a different word or phrase.
      </p>
      <div className="grid-outer">
        <div className="grid">
          <div className="no-results">
            <p>
              <strong>Sorry, there are no products here.</strong>
            </p>
          </div>
        </div>
      </div>
    </>
  )
}
===== features/search/SearchToolbar.tsx
import { useFacets } from "@nosto/search-js/preact/hooks"
import { cl } from "@nosto/search-js/utils"
import FilterButton from "@/shared/toolbar/FilterButton"
import SortPopout from "@/shared/toolbar/SortPopout"

/**
 * Search page bar (sections/search.liquid): filter button and sort dropdown, styled by collection-bar.css.
 * Sort isn't repeated in the drawer here.
 */
export default function SearchToolbar() {
  // Facets are set up in Nosto Admin (Search → Facets); without them there is nothing to filter
  const { facets } = useFacets()
  const hasFacets = !!facets?.length

  return (
    <nav
      aria-label="Sort and filters"
      className={cl("collection__nav collection__nav--sort", hasFacets && "collection__nav--filter")}
    >
      {hasFacets && (
        <div className="popout--group">
          <FilterButton />
        </div>
      )}
      <SortPopout />
    </nav>
  )
}

