import { useLoadMore, useNostoAppState } from "@nosto/search-js/preact/hooks"
import { cl } from "@nosto/search-js/utils"
import { getPageSize } from "@/lib/themeSettings"
import ThemeLoader from "@/elements/ThemeLoader"

/**
 * "Load more" button that appends the next page. Uses the theme's button and its loading spinner.
 */
export default function LoadMore() {
  const { loadMore } = useLoadMore(getPageSize())
  const { loading, shown, total } = useNostoAppState(state => ({
    loading: state.loading,
    shown: state.response.products?.hits.length ?? 0,
    total: state.response.products?.total ?? 0
  }))

  if (shown >= total) {
    return null
  }

  return (
    <div className="pagination">
      <button
        type="button"
        className={cl("btn btn--primary btn--outline", loading && "is-loading")}
        disabled={loading}
        onClick={loadMore}
      >
        <span className="btn__text">Load more</span>
        <ThemeLoader />
      </button>
    </div>
  )
}
