/**
 * Copied from the theme's snippets/icon-{name}.liquid (Elie_Tahari_TAHARI_2026), so theme.css sizes and
 * colours them via `.icon` / `.icon-{name}`. Keep in sync if the theme's icons change.
 *
 * The nav arrows are filled triangles with their own viewBox, not the stroked 24x24 chevrons other
 * Broadcast themes ship — so each icon carries its own geometry rather than sharing one.
 */
const icons = {
  "nav-arrow-down": {
    width: 6,
    height: 5,
    viewBox: "0 0 6 5",
    d: "M3.07176 4.8C2.95629 5 2.66761 5 2.55214 4.8L0.0406694 0.45C-0.074801 0.249999 0.0695371 -6.8892e-08 0.300477 -4.87026e-08L5.32343 3.90417e-07C5.55437 4.10607e-07 5.6987 0.25 5.58323 0.45L3.07176 4.8Z",
    fill: undefined,
    stroke: undefined
  },
  "nav-arrow-left": {
    width: 8,
    height: 9,
    viewBox: "0 0 8 9",
    d: "M0.150196 4.37065C-0.0498036 4.25518 -0.049804 3.9665 0.150196 3.85103L6.7502 0.0405206C6.9502 -0.0749493 7.2002 0.0693884 7.2002 0.300328L7.2002 7.92135C7.2002 8.15229 6.9502 8.29663 6.7502 8.18116L0.150196 4.37065Z",
    fill: "#211918",
    stroke: undefined
  },
  "nav-arrow-right": {
    width: 8,
    height: 9,
    viewBox: "0 0 8 9",
    d: "M7.05 3.85103C7.25 3.9665 7.25 4.25518 7.05 4.37065L0.45 8.18116C0.25 8.29663 -3.95214e-07 8.15229 -3.8512e-07 7.92135L-5.19942e-08 0.300328C-4.18995e-08 0.069388 0.25 -0.0749501 0.45 0.0405199L7.05 3.85103Z",
    fill: "#211918",
    stroke: undefined
  },
  /** Drawer close button and active-filter chips */
  cancel: {
    width: undefined,
    height: undefined,
    viewBox: "0 0 24 24",
    d: "M6.758 17.243 12.001 12m5.243-5.243L12 12m0 0L6.758 6.757M12.001 12l5.243 5.243",
    fill: "none",
    stroke: "currentColor"
  },
  /** "More options" in a facet group */
  "arrow-separate-vertical": {
    width: undefined,
    height: undefined,
    viewBox: "0 0 24 24",
    d: "M15.5 9.5 12 6 8.5 9.5m7 4.5L12 17.5 8.5 14",
    fill: "none",
    stroke: "#000"
  }
} as const

type Props = {
  name: keyof typeof icons
}

export default function ThemeIcon({ name }: Props) {
  const { width, height, viewBox, d, fill, stroke } = icons[name]
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      role="presentation"
      className={`icon icon-${name}`}
      width={width}
      height={height}
      viewBox={viewBox}
      fill="none"
    >
      <path d={d} fill={fill} stroke={stroke} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

