import { useLayoutEffect, useRef } from "preact/hooks"
import { selectors } from "@/lib/themeSettings"

/**
 * The theme's Model | Product switcher (snippets/collection-model-switcher.liquid), cloned from the
 * `<template data-nosto-model-switcher>` the search section renders. Cloning parsed HTML lets the theme's
 * <collection-model-switcher> custom element upgrade normally; it must not be rendered through JSX.
 * Its script (collection-model-switcher.js) swaps card images, including cards Nosto adds later.
 */
export default function ThemeModelSwitcher() {
  const ref = useRef<HTMLSpanElement>(null)

  useLayoutEffect(() => {
    const template = document.querySelector<HTMLTemplateElement>(selectors.modelSwitcher)
    const container = ref.current
    if (!template || !container) return
    container.replaceChildren(template.content.cloneNode(true))
  }, [])

  return <span ref={ref} style={{ display: "contents" }} />
}

