import { useFacets } from "@nosto/search-js/preact/hooks"
import { cl } from "@nosto/search-js/utils"
import FilterButton from "@/shared/toolbar/FilterButton"
import SortPopout from "@/shared/toolbar/SortPopout"
import ThemeModelSwitcher from "@/elements/ThemeModelSwitcher"
import { getToolbarSettings } from "@/lib/themeSettings"
import { strings } from "@/lib/i18n"

/**
 * Search page bar (sections/search.liquid `nav.collection__nav`), styled by collection-bar.css: filter
 * button, sort dropdown and the theme's Model | Product image switcher. Sort isn't repeated in the drawer
 * here. The section's own `enable_sort` / `enable_filters` settings reach us as mount data attributes.
 */
export default function SearchToolbar() {
  const { sort: sortEnabled, filters: filtersEnabled } = getToolbarSettings()
  // Facets are set up in Nosto Admin (Search → Facets); without them there is nothing to filter
  const { facets } = useFacets()
  const showFilters = filtersEnabled && !!facets?.length

  if (!sortEnabled && !filtersEnabled) {
    return null
  }

  return (
    <nav
      aria-label={strings().sortAndFilters}
      className={cl("collection__nav", sortEnabled && "collection__nav--sort", showFilters && "collection__nav--filter")}
      data-collection-nav
    >
      {showFilters && (
        <div className="popout--group">
          <FilterButton />
        </div>
      )}
      {sortEnabled && <SortPopout />}
      <ThemeModelSwitcher />
    </nav>
  )
}

