import { useFacets, useNostoAppState } from "@nosto/search-js/preact/hooks"
import { cl } from "@nosto/search-js/utils"
import FilterButton from "@/shared/toolbar/FilterButton"
import SortPopout from "@/shared/toolbar/SortPopout"
import ShortcutFilters from "./ShortcutFilters"

/**
 * Collection page bar (sections/collection.liquid): "Sort & Filter" button with the shortcut filters, and the
 * product count where search shows the sort dropdown. Sort lives in the drawer here; without facets there's no
 * drawer, so the bar shows the sort dropdown instead (as the theme does when filters are off).
 */
export default function PlpToolbar() {
  const { facets } = useFacets()
  const hasFacets = !!facets?.length

  return (
    <nav
      aria-label="Sort and filters"
      className={cl("collection__nav", hasFacets ? "collection__nav--filter" : "collection__nav--sort")}
    >
      {hasFacets ? (
        <>
          <div className="popout--group popout--group-rs-filters">
            <FilterButton label="Sort & Filter" />
            <ShortcutFilters />
          </div>
          <ProductCount />
        </>
      ) : (
        <SortPopout />
      )}
    </nav>
  )
}

/** "N products" (theme string general.products_with_count); blank while skeleton results show */
function ProductCount() {
  const { total, skeleton } = useNostoAppState(state => ({
    total: state.response.products?.total ?? 0,
    skeleton: !!state.response.products?.hits?.[0]?.tags1?.includes("skeleton")
  }))

  return (
    <span className="rs-collection-count">{skeleton ? " " : `${total} ${total === 1 ? "product" : "products"}`}</span>
  )
}

