import { Product } from "@/types"
import { SerpElement } from "@nosto/search-js/preact/serp"
import { AutocompleteElement } from "@nosto/search-js/preact/autocomplete"
import DynamicCard from "@/elements/DynamicCard"
import { mockThemeCards } from "@/config"

/**
 * Theme sections that render each card type (fetched as /products/{handle}?section_id={section}).
 */
export const cardSections = {
  grid: "api-nosto-product-card",
  "grid-no-quick-view": "api-nosto-product-card-mini",
  list: "api-nosto-product-card-list"
} as const

export type CardType = keyof typeof cardSections

type Props = {
  product: Product
  type?: CardType
  /** Which Nosto click event the card records: search page (default) or autocomplete dropdown */
  context?: "serp" | "autocomplete"
}

/**
 * Product card rendered by the Shopify theme, so markup, styles and quick view match the theme exactly.
 *
 * Usage:
 *   <ProductCard product={hit} />                            // regular card (product-grid-item)
 *   <ProductCard product={hit} type="grid-no-quick-view" />  // product-grid-item with hide_quick_add
 *   <ProductCard product={hit} type="list" />                // list card (upsell-product)
 *   <ProductCard product={hit} context="autocomplete" />     // inside the autocomplete dropdown
 *
 * Grid types go inside the theme grid (`<div class="grid">`). A skeleton styled like the card type holds the
 * card's space until the theme HTML lands (and stands in for skeleton hits, see `skeletonLoading` in config.ts). Keep the SerpElement/AutocompleteElement wrapper so Nosto tracks product clicks.
 */
export default function ProductCard({ product, type = "grid", context = "serp" }: Props) {
  const Skeleton = type === "list" ? ListSkeleton : GridSkeleton

  if (product.tags1?.includes("skeleton")) {
    return <Skeleton />
  }

  if (!product.handle) {
    return null
  }

  const Element = context === "autocomplete" ? AutocompleteElement : SerpElement

  return (
    <div className="ns-card-cell">
      <Element
        as={DynamicCard}
        hit={{
          productId: product.productId!,
          url: product.url
        }}
        componentProps={{
          handle: product.handle,
          section: cardSections[type],
          lazy: true,
          mock: mockThemeCards
        }}
      />
      {!mockThemeCards && <Skeleton />}
    </div>
  )
}

/**
 * Mirrors the markup of product-grid-item.liquid so theme.css gives it the same size as the real card.
 */
function GridSkeleton() {
  return (
    <div
      className={"grid-item product-item product-item--left product-item--outer-text ns-skeleton"}
      aria-hidden="true"
    >
      <div className="product-item__image">
        <div className={"ns-shimmer ns-skeleton-image"} />
      </div>
      <div className="product-information" style={{ "--swatch-size": "var(--swatch-size-filters)" }}>
        <div className="product-item__info body-medium">
          <div className="product-item__swatches rs-card-swatches">
            <span className="rs-card-swatches__swatch swatches swatch__button swatch__button--circle">
              <span className="sibling__link" />
            </span>
          </div>
          <div className="product-link">
            <p className="product-item__title font-product-title">
              <span className="ns-shimmer ns-skeleton-text">Product title</span>
            </p>
            <div className="product-item__price__holder body-small">
              <div className="product-item__price">
                <span className="ns-shimmer ns-skeleton-text">$00.00</span>
              </div>
            </div>
          </div>
          <div className="product-item__timeline rs-card-timeline body-x-small">
            <span className="ns-shimmer ns-skeleton-text">Ships Immediately</span>
          </div>
        </div>
      </div>
    </div>
  )
}

function ListSkeleton() {
  return (
    <div className={"product-upsell__holder ns-skeleton"} aria-hidden="true">
      <div className="product-upsell">
        <div className="product-upsell__image">
          <div className={"product-upsell__image__thumb ns-shimmer"} />
        </div>
        <div className="product-upsell__content">
          <p className="product-upsell__title font-product-title heading-medium">
            <span className="ns-shimmer ns-skeleton-text">Product title</span>
          </p>
          <div className="product-upsell__price">
            <span className="ns-shimmer ns-skeleton-text">$00.00</span>
          </div>
        </div>
      </div>
    </div>
  )
}
===== styles.css
/*
 * The only Nosto stylesheet. Components use the theme's markup and classes, so theme CSS does the styling;
 * this file holds the glue between Nosto markup and theme CSS, plus the few Nosto-only pieces (`ns-` classes).
 * Loaded once from entries/injected.tsx.
 */

/* == Product cards (shared/ProductCard) == */

/* Not `display: contents`: `lazy` cards wait for an IntersectionObserver, which never fires for a box-less element. */
nosto-dynamic-card {
  display: block;
}

nosto-dynamic-card[empty],
nosto-dynamic-card[error] {
  display: none;
}

/* Grid cell holding the theme card and its skeleton, so the grid keeps its size while cards load */
.ns-card-cell:has(> nosto-dynamic-card[empty]),
.ns-card-cell:has(> nosto-dynamic-card[error]) {
  display: none;
}

/* The card is empty until its theme HTML lands */
.ns-card-cell > nosto-dynamic-card:not(:empty) + .ns-skeleton {
  display: none;
}

.ns-skeleton {
  pointer-events: none;
}

.ns-shimmer {
  background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
  background-size: 200% 100%;
  animation: ns-shimmer 1.5s infinite;
}

.ns-skeleton-text {
  display: inline-block;
  color: transparent;
}

/* Fills the theme's card image box, which already reserves the image ratio */
.ns-skeleton-image {
  position: absolute;
  inset: 0;
}

@keyframes ns-shimmer {
  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }
}

/* Theme-rendered grid tiles (editorial images): the wrapper mustn't be a grid cell, so the tile's span classes apply */
.ns-grid-tile {
  display: contents;
}

/* == Autocomplete (features/autocomplete) == */

/* Theme hides .predictive-search until its own <predictive-search> opens it; Nosto only renders it when there are results */
[data-nosto-autocomplete] .predictive-search {
  opacity: 1;
  visibility: visible;
}

/* The theme sets this on <predictive-search>, which isn't rendered when Nosto search is on (global default is 1) */
[data-nosto-autocomplete] {
  --COLUMNS-MOBILE: 2;
}

/* == Filter drawer (shared/filters) == */

/*
 * The theme re-renders its drawer after every change, which resets these; ours stays
 * mounted, so:
 * - the drawer only scrolls vertically (subpixel rounding can otherwise add a 1px horizontal scrollbar)
 * - lists and group bodies clip instead of hide: focusing a checkbox scrolled the `overflow: hidden` list, pushing
 *   the first rows under the group heading
 */
[data-nosto-filters] .collection__sidebar {
  overflow-x: hidden;
}

[data-nosto-filters] .collection-nav,
[data-nosto-filters] [data-collapsible-body] {
  overflow: clip;
}

/* Current min/max under the price slider (the theme shows From/To inputs here, which Nosto doesn't need) */
.ns-range-values {
  display: flex;
  justify-content: space-between;
  margin-top: 4px;
  color: var(--text-a50);
}

