import { useNostoAppState, useResponse } from "@nosto/search-js/preact/hooks"
import { AutocompleteElement } from "@nosto/search-js/preact/autocomplete"
import { SearchCategory, SearchKeyword, SearchPopularSearch } from "@nosto/nosto-js/client"
import { ComponentChildren } from "preact"
import { cl } from "@nosto/search-js/utils"
import ProductCard from "@/shared/ProductCard"
import { useRovingFocus } from "@/lib/hooks/useRovingFocus"
import { searchPath } from "@/config"
import { QUERY_PARAM } from "@/lib/queryState"
import { useOnSubmit } from "./OnSubmitContext"
import { getAutocompleteSettings } from "@/lib/themeSettings"
import { useLayoutEffect, useRef, useState } from "preact/hooks"

type Props = {
  onKeyDown: (e: KeyboardEvent) => void
}

/**
 * Autocomplete dropdown using the theme's predictive search markup (sections/predictive-search.liquid),
 * so predictive-search.css styles it. Products are theme cards without quick view. Which groups show
 * comes from "RS: Nosto Settings" → Header search (lib/themeSettings.ts).
 */
export default function AutocompleteResults({ onKeyDown }: Props) {
  const { keywords, categories, popularSearches, products } = useResponse()
  const query = useNostoAppState(state => state.query?.query)
  const containerRef = useRovingFocus<HTMLDivElement>(".ns-autocomplete-element")
  const [settings] = useState(getAutocompleteSettings)

  // Disabled groups aren't requested; filtering here also covers responses cached before a setting changed
  const keywordHits = settings.suggestions ? (keywords?.hits ?? []) : []
  const categoryHits = settings.collections ? (categories?.hits ?? []) : []
  const popularSearchHits = settings.popularSearches ? (popularSearches?.hits ?? []) : []
  const productHits = products?.hits ?? []
  const hasSuggestionsColumn =
    settings.searchButton || [keywordHits, categoryHits, popularSearchHits].some(hits => hits.length > 0)
  const visible = !!query && [keywordHits, categoryHits, popularSearchHits, productHits].some(hits => hits.length > 0)
  const resultsRef = useResultsHeight(visible)

  if (!visible) {
    return null
  }

  return (
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions
    <div
      ref={resultsRef}
      className="predictive-search"
      data-nosto-element="autocomplete"
      data-scroll-lock-scrollable
      onKeyDown={onKeyDown}
    >
      <div className="wrapper--full-padded" ref={containerRef}>
        <div
          className={cl(
            "predictive-search__layout",
            !productHits.length && "predictive-search__layout--no-products",
            !hasSuggestionsColumn && "predictive-search__layout--no-suggestions"
          )}
        >
          {hasSuggestionsColumn && (
            <div className="predictive-search__column">
              {keywordHits.length > 0 && (
                <Group heading="Suggestions">
                  {keywordHits.map(keyword => (
                    <Keyword key={keyword.keyword} keyword={keyword} />
                  ))}
                </Group>
              )}
              {categoryHits.length > 0 && (
                <Group heading="Collections">
                  {categoryHits.map(category => (
                    <Category key={category.url} category={category} />
                  ))}
                </Group>
              )}
              {popularSearchHits.length > 0 && (
                <Group heading="Popular searches">
                  {popularSearchHits.map(search => (
                    <PopularSearch key={search.query} search={search} />
                  ))}
                </Group>
              )}
              {settings.searchButton && (
                <div className="predictive-search__actions">
                  <button type="submit" className="btn btn--outline btn--primary">
                    Search for &quot;{query}&quot;
                  </button>
                </div>
              )}
            </div>
          )}
          {productHits.length > 0 && (
            <div className="predictive-search__column">
              <div className="predictive-search__group">
                <p className="predictive-search__heading body-small">Products</p>
                <div className="predictive-search__products__list grid-outer">
                  <div className="grid">
                    {productHits.map(hit => (
                      <ProductCard key={hit.productId} product={hit} type="grid-no-quick-view" context="autocomplete" />
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

/**
 * Caps the dropdown at the visible viewport so it scrolls, like PredictiveSearch.open() in theme.dev.js.
 */
function useResultsHeight(visible: boolean) {
  const ref = useRef<HTMLDivElement>(null)

  useLayoutEffect(() => {
    const element = ref.current
    if (!visible || !element) return

    function update() {
      const viewportHeight = window.visualViewport?.height ?? window.innerHeight
      element!.style.setProperty("--results-height", `${viewportHeight - element!.getBoundingClientRect().top}px`)
    }

    update()
    window.addEventListener("resize", update)
    return () => window.removeEventListener("resize", update)
  }, [visible])

  return ref
}

function Keyword({ keyword }: { keyword: SearchKeyword }) {
  const onSubmit = useOnSubmit()

  function onClick(e: Event) {
    e.preventDefault()
    if (keyword._redirect) {
      window.location.href = keyword._redirect
    } else {
      onSubmit(keyword.keyword, { isKeyword: true })
    }
  }

  return (
    <div className="predictive-search__item">
      <AutocompleteElement
        hit={keyword}
        as="a"
        componentProps={{
          className: "predictive-search__link",
          href: searchUrl(keyword.keyword),
          onClick
        }}
      >
        {keyword._highlight?.keyword ? (
          <span dangerouslySetInnerHTML={{ __html: keyword._highlight.keyword }} />
        ) : (
          keyword.keyword
        )}
      </AutocompleteElement>
    </div>
  )
}

function Group({ heading, children }: { heading: string; children: ComponentChildren }) {
  return (
    <div className="predictive-search__group">
      <p className="predictive-search__heading body-small">{heading}</p>
      {children}
    </div>
  )
}

function Category({ category }: { category: SearchCategory }) {
  return (
    <div className="predictive-search__item">
      <AutocompleteElement
        hit={category}
        as="a"
        componentProps={{ className: "predictive-search__link", href: category.url }}
      >
        {category.fullName ?? category.name}
      </AutocompleteElement>
    </div>
  )
}

function PopularSearch({ search }: { search: SearchPopularSearch }) {
  const onSubmit = useOnSubmit()
  const query = search.query!

  function onClick(e: Event) {
    e.preventDefault()
    onSubmit(query, { isPopular: true })
  }

  return (
    <div className="predictive-search__item">
      <AutocompleteElement
        hit={{ keyword: query }}
        as="a"
        componentProps={{ className: "predictive-search__link", href: searchUrl(query), onClick }}
      >
        {query}
      </AutocompleteElement>
    </div>
  )
}

function searchUrl(query: string) {
  return `${searchPath}?${QUERY_PARAM}=${encodeURIComponent(query)}`
}

