import { fireEvent, render } from "@testing-library/preact"
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest"
import { mockNostojs } from "@nosto/nosto-js/testing"
import { http, HttpResponse } from "msw"
import "@nosto/web-components"
import { SearchPageProvider } from "@nosto/search-js/preact/serp"
import { createStore } from "@nosto/search-js/preact/common"
import { mockConfig, mockInitialState } from "@mocks/mocks"
import ProductCard, { CardType } from "@/shared/ProductCard"
import { Product } from "@/types"
import { addHandlers } from "../setup/msw.setup"
import { MockIntersectionObserver } from "../setup/MockIntersectionObserver"

const product = {
  productId: "6992961568852",
  url: "https://www.baublebar.com/products/bubble-initial-necklace-gold",
  handle: "bubble-initial-necklace-gold"
} satisfies Product

function renderCard(props: { product?: Product; type?: CardType; context?: "serp" | "autocomplete" } = {}) {
  const { container } = render(
    <SearchPageProvider config={mockConfig} store={createStore(mockInitialState)}>
      <ProductCard product={product} {...props} />
    </SearchPageProvider>
  )
  return container
}

function renderDynamicCard(props: Parameters<typeof renderCard>[0] = {}) {
  return renderCard(props).querySelector("nosto-dynamic-card")
...
    const card = renderDynamicCard()
    expect(card?.getAttribute("handle")).toBe(product.handle)
    expect(card?.getAttribute("section")).toBe("api-nosto-product-card")
  })

  it.each([
    ["grid-no-quick-view", "api-nosto-product-card-mini"],
    ["list", "api-nosto-product-card-list"]
  ] as const)("renders the %s type with section %s", (type, section) => {
    expect(renderDynamicCard({ type })?.getAttribute("section")).toBe(section)
  })

  it("renders nothing without a handle", () => {
    expect(renderCard({ product: { ...product, handle: undefined } }).innerHTML).toBe("")
  })

  it.each([
    ["grid", ".product-item__image"],
    ["grid-no-quick-view", ".product-item__image"],
    ["list", ".product-upsell__image"]
  ] as const)("renders a %s skeleton for skeleton hits", (type, selector) => {
    const container = renderCard({ product: { ...product, tags1: ["skeleton"] }, type })
    expect(container.querySelector("nosto-dynamic-card")).toBeNull()
    expect(container.querySelector(`[aria-hidden='true'] ${selector}`)).toBeTruthy()
  })

  it.each(["serp", "autocomplete"] as const)("records a %s click for the hit", context => {
    const recordSearchClick = vi.fn()
    mockNostojs({ recordSearchClick })
    fireEvent.click(renderDynamicCard({ context })!)
    expect(recordSearchClick).toHaveBeenCalledWith(context, { productId: product.productId, url: product.url })

