toolUseResult.newString:
/**
 * `replaceState`, never `pushState`. Each appended page would otherwise add a history entry, so one Back
 * press lands inside the same results page instead of leaving it — and on this store the theme's own
 * popstate handler then refetched and rebuilt the grid, dropping every loaded page. Measured on the
 * collection page; see the vault's plp-infinite-scroll-and-swatch-fetch pattern note.
 */
export function updateUrl(state: UrlQueryState) {
  const url = getUrlFromState(state)
  const absolute = new URL(url, window.location.href).toString()
  if (window.location.href === absolute) {
    return
  }
  window.history.replaceState(null, "", url)
}

toolUseResult.originalFile:
import { SearchQuery } from "@nosto/nosto-js/client"
import { appendsPages, getPageSize } from "@/lib/themeSettings"
import { UrlQueryState, SimpleQuery, serializeQueryState, deserializeQueryState } from "@/lib/queryState"

// Reads and writes the browser URL for the current search state.

export function getCurrentUrlState() {
  const searchParams = new URLSearchParams(window.location.search)
  return deserializeQueryState(searchParams)
}

function fromPageParameters(urlSize: number | undefined, page: number | undefined) {
  const size = urlSize ?? getPageSize()
  if (appendsPages()) {
    return {
      from: 0,
      size: (page ?? 1) * size
    }
  }
  return {
    from: page ? (page - 1) * size : 0,
    size
  }
}

export function getQueryFromUrlState() {
  const { query, page, size: urlSize, filter, sort } = getCurrentUrlState()
  return {
    query,
    products: {
      ...fromPageParameters(urlSize, page),
      filter,
      sort
    }
  } satisfies SearchQuery
}

export function getUrlFromState(state: UrlQueryState) {
  const params = new URLSearchParams(window.location.search || "")
  serializeQueryState(state, params)

  const url = new URL(window.location.pathname, window.location.origin)
  url.search = params.toString()

  return url.pathname + url.search
}

const initialUrlState = getCurrentUrlState()

export function getInitialQuery() {
  return initialUrlState.query || ""
}

export function getPageUrl(page: number) {
  const currentState = getCurrentUrlState()
  return getUrlFromState({
    ...currentState,
    page: page > 1 ? page : undefined
  })
}

export function updateUrl(state: UrlQueryState) {
  const url = getUrlFromState(state)
  const absolute = new URL(url, window.location.href).toString()
  if (window.location.href === absolute) {
    return
  }
  window.history.pushState(null, "", url)
}

function toPageParameters(from: number | undefined, size: number) {
  if (appendsPages()) {
    return {
      page: Math.floor(size / getPageSize())
    }
  }
  return {
    page: from ? Math.floor(from / size) + 1 : 1,
    size
  }
}

export function updateUrlFromQuery({ from, size, query, filter, sort }: SimpleQuery) {
  updateUrl({
    ...toPageParameters(from, size),
    query,
    filter,
    sort
  })
}

