async () => {
  for (let i = 0; i < 25 && typeof window.nostojs !== 'function'; i++) await new Promise(r => setTimeout(r, 300));
  const base = {
    themeId: window.Shopify?.theme?.id,
    themeName: window.Shopify?.theme?.name,
    nostojs: typeof window.nostojs,
    nostoScript: [...document.scripts].map(s => s.src).find(s => /nosto/i.test(s)),
    mounts: {
      search: !!document.querySelector('[data-nosto-search]'),
      autocomplete: document.querySelectorAll('[data-nosto-autocomplete]').length,
      i18n: !!document.querySelector('[data-nosto-i18n]')
    }
  };
  if (typeof window.nostojs !== 'function') return base;
  const settings = await new Promise(res => nostojs(api => res(api.internal?.getSettings?.() || {})));
  return { ...base, account: settings.account, searchEnabled: settings.searchEnabled,
    searchTemplatesEnabled: settings.searchTemplatesEnabled, searchApiUrl: settings.searchApiUrl,
    searchTemplateHost: settings.searchTemplateHost, searchDeploymentId: settings.searchDeploymentId,
    categoriesEnabled: settings.categoriesEnabled, currencies: Object.keys(settings.currencySettings || {}) };
}

