input.function:
async () => {
  const html = await fetch('/search?q=dress', { cache: 'no-store' }).then(r => r.text());
  const m = html.match(/data-nosto-i18n[^>]*>([\s\S]{0,800}?)<\/script>/);
  let parsed = null, err = null;
  if (m) { try { parsed = JSON.parse(m[1]) } catch (e) { err = String(e).slice(0, 120) } }
  return {
    liquidErrors: [...html.matchAll(/Liquid error[^<]{0,120}/g)].map(x => x[0]).slice(0, 2),
    i18nPresent: !!m,
    parseError: err,
    keys: parsed ? Object.keys(parsed).length : null,
    sample: parsed ? { filters: parsed.filters, sort: parsed.sort, showMore: parsed.showMore, sortOptions: parsed.sortOptions } : null
  };
}

