input.function:
async () => {
  const html = await fetch('/search?q=dress', { cache: 'no-store' }).then(r => r.text());
  const el = document.querySelector('[data-nosto-i18n]');
  let parsed = null, err = null;
  if (el) { try { parsed = JSON.parse(el.textContent) } catch (e) { err = String(e).slice(0, 150) } }
  return {
    themeId: window.Shopify?.theme?.id,
    themeName: window.Shopify?.theme?.name,
    liquidErrors: [...html.matchAll(/Liquid error[^<]{0,120}/g)].map(x => x[0]).slice(0, 2),
    i18nPresent: !!el,
    parseError: err,
    strings: parsed
  };
}

