import json,pathlib
d=json.loads(pathlib.Path('config/settings_schema.json').read_text())
for g in d:
    if not isinstance(g,dict): continue
    ids=[s.get('id') for s in g.get('settings',[]) if isinstance(s,dict)]
    if any(i and 'nosto' in str(i).lower() for i in ids):
        print("GROUP:", g.get('name'))
        for s in g.get('settings',[]):
            if isinstance(s,dict):
                mark = "  <<<" if s.get('id')=='rs_nosto_search_enabled' else ""
                print(f"   {s.get('type','header'):10} {str(s.get('id') or s.get('content','')):35} {str(s.get('label',''))[:45]}{mark}")
PY

