input.new_string:
function readThemeStrings(): Partial<Strings> | undefined {
  const json = document.querySelector(selectors.i18n)?.textContent
  if (!json) return undefined
  try {
    return decodeDeep(JSON.parse(json)) as Partial<Strings>
  } catch {
    return undefined
  }
}

/**
 * Shopify's `t` filter HTML-escapes translations, so a string like `Search for "{terms}"` arrives as
 * `Search for &quot;{terms}&quot;`. Liquid has no unescape filter, so decode here instead — otherwise the
 * entities render literally. Covers nested values too (sortOptions is an object).
 */
function decodeDeep<T>(value: T): T {
  if (typeof value === "string") return decodeEntities(value) as T
  if (Array.isArray(value)) return value.map(decodeDeep) as T
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, inner]) => [key, decodeDeep(inner)])) as T
  }
  return value
}

function decodeEntities(value: string) {
  if (!value.includes("&")) return value
  // A textarea decodes entities without running markup; the source is our own theme snippet
  const element = document.createElement("textarea")
  element.innerHTML = value
  return element.value
}

