content.content:
  {%- render 'search-form' -%}

  {%- if settings.rs_nosto_search_enabled -%}
    {%- comment -%}
      Nosto search (template code: roswell-studios/Elie_Tahari_TAHARI_Nosto) portals the results into
      [data-nosto-search]. Products only: Shopify's page/article results are intentionally not shown.
      The [data-products-grid] wrapper must exist at page load: card-scroller-window.js and
      collection-model-switcher.js attach to it then and pick up Nosto's cards through MutationObservers.
      The <template> hands Nosto the theme's Model | Product switcher markup.
    {%- endcomment -%}
    {%- render 'product-grid-scripts' -%}
    {%- render 'stylesheet', name: 'pagination-custom.css' -%}

    <template data-nosto-model-switcher>
      {%- render 'collection-model-switcher' -%}
    </template>

    <div data-products-grid>
      <div
        data-nosto-search
        data-card-image-mode="{{ section.settings.card_image_mode | default: 'model' }}"
        data-filter-layout="{{ filter_layout }}"
        data-enable-sort="{{ enable_sort }}"
        data-enable-filters="{{ enable_filters }}"
      ></div>
    </div>
  {%- elsif search.performed -%}
    {%- capture search_results -%}
      {%- paginate search.results by 36 -%}
        {%- render 'product-grid-scripts' -%}
