          {%- comment -%}
            Nosto's autocomplete mount. The data-* attributes are its settings ("RS: Nosto Settings" →
            Header search); grid columns are CSS variables, which Nosto never reads.
          {%- endcomment -%}
          {%- render 'nosto-i18n' -%}
          {%- liquid
            assign rs_ac_columns_desktop = settings.rs_nosto_ac_columns_desktop | default: 3
            assign rs_ac_columns_mobile = settings.rs_nosto_ac_columns_mobile | default: 2
            assign rs_ac_columns_medium = rs_ac_columns_desktop | at_most: 3
          -%}
          <div
            data-nosto-autocomplete
            data-suggestions="{{ settings.rs_nosto_ac_suggestions }}"
            data-collections="{{ settings.rs_nosto_ac_collections }}"
            data-popular-searches="{{ settings.rs_nosto_ac_popular_searches }}"
            data-search-button="{{ settings.rs_nosto_ac_search_button }}"
            data-products="{{ settings.rs_nosto_ac_products }}"
            style="--COLUMNS: {{ rs_ac_columns_desktop }}; --COLUMNS-MEDIUM: {{ rs_ac_columns_medium }}; --COLUMNS-MOBILE: {{ rs_ac_columns_mobile }};"
          ></div>"""
s = s.replace(a, b)
p.write_text(s)
