input.function:
async () => {
  await new Promise(r => setTimeout(r, 3000));
  const mount = document.querySelector('[data-nosto-search]');
  const ac = document.querySelector('[data-nosto-autocomplete]');
  return {
    themeId: window.Shopify?.theme?.id,
    searchMount: mount ? Object.assign({}, mount.dataset) : null,
    gridWrapperStyle: mount?.closest('[data-products-grid]')?.getAttribute('style'),
    autocompleteSettings: ac ? Object.assign({}, ac.dataset) : null,
    i18nPresent: !!document.querySelector('[data-nosto-i18n]'),
    // is the debug toolbar in the DOM at all?
    debugToolbar: !!document.querySelector('[id*="nosto-debug" i], [class*="nosto-debug" i], iframe[src*="nosto"]'),
    nostoIframes: [...document.querySelectorAll('iframe')].map(f => f.src).filter(s => /nosto/i.test(s)).slice(0, 3)
  };
}

