input.function:
async () => {
  await new Promise(r => setTimeout(r, 2500));
  const res = performance.getEntriesByType('resource')
    .filter(r => /search\/templates|cloudfront.*search|bundle\.(js|css)/i.test(r.name));
  return {
    page: 'homepage',
    templateAssets: res.map(r => ({
      url: r.name.replace(/^https?:\/\/[^/]+/, '…'),
      kb: Math.round((r.transferSize || r.encodedBodySize || 0) / 1024),
      ms: Math.round(r.duration)
    })),
    hasSearchMount: !!document.querySelector('[data-nosto-search]'),
    autocompleteMounts: document.querySelectorAll('[data-nosto-autocomplete]').length
  };
}

