    predictiveSearchEl: document.querySelectorAll('predictive-search').length,
    liquidGrid: !!document.querySelector('#SearchLoop'),
    bundleLoaded: performance.getEntriesByType('resource').some(r => /search\/templates.*bundle\.js/.test(r.name)),
    mountEmpty: mount ? mount.innerHTML.trim() === '' : null
  };
}

