input.function:
async () => {
  // wait for Nosto results to render
  for (let i = 0; i < 40; i++) {
    const m = document.querySelector('[data-nosto-search]');
    if (m && m.innerHTML.trim() !== '') break;
    await new Promise(r => setTimeout(r, 400));
  }
  await new Promise(r => setTimeout(r, 2500));
  const m = document.querySelector('[data-nosto-search]');
  const cards = [...document.querySelectorAll('nosto-dynamic-card')];
  return {
    themeId: window.Shopify?.theme?.id,
    bundleLoaded: performance.getEntriesByType('resource').some(r => /search\/templates.*bundle\.js/.test(r.name)),
    mountRendered: !!m && m.innerHTML.trim() !== '',
    caption: document.querySelector('.search__caption')?.textContent?.trim().slice(0, 80),
    toolbar: !!document.querySelector('.collection__nav'),
    sortLabel: document.querySelector('.popout--sort .popout__toggle')?.textContent?.replace(/\s+/g,' ').trim(),
    filterButton: document.querySelector('.popout--group .popout__toggle')?.textContent?.trim(),
    switcher: !!document.querySelector('collection-model-switcher'),
    cards: cards.length,
    filledCards: cards.filter(c => c.innerHTML.trim()).length,
    firstCardTitle: cards[0]?.querySelector('.product-item__title')?.textContent?.trim(),
    pagination: !!document.querySelector('.pagination-custom'),
    skeletons: document.querySelectorAll('.ns-skeleton').length
  };
}

