input.function:
async () => {
  const res = await fetch('https://search.nosto.com/api/', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      query: `{ search(accountId:"shopify-35089973385", query:"", products:{size:1}) { products { total } } }`
    })
  }).then(r => r.json()).catch(e => ({ error: String(e) }));
  const filterBtn = document.querySelector('.popout--group .popout__toggle');
  return {
    nostoTotalCatalog: res?.data?.search?.products?.total ?? res,
    filterButtonInDom: !!filterBtn,
    filterButtonVisible: filterBtn ? filterBtn.getBoundingClientRect().width > 0 : null,
    facetsOnPage: document.querySelectorAll('.filter-group').length
  };
}

