input.command:
cd ~/Documents/roswell-studios/Elie_Tahari_TAHARI_Nosto && node -e '
const fs=require("fs");
try{
  const raw=fs.readFileSync(".nosto.json","utf8");
  const j=JSON.parse(raw);
  console.log("valid JSON. keys:", Object.keys(j).join(", "));
  console.log("merchant:", j.merchant ?? "(MISSING)");
  console.log("has apiKey:", "apiKey" in j);
}catch(e){ console.log("PARSE ERROR:", e.message); console.log("raw length:", fs.readFileSync(".nosto.json","utf8").length); }'

